// =========================================================
// BRICK 307 — DEVELOPMENT PREREQUISITE GRANT
// =========================================================
//
// Explicit developer helper.
//
// Does not run automatically.
//
// Uses existing addItemToInventory() so instance creation
// remains under current Inventory authority.
//
// =========================================================

function grantAcademyPilotEquipmentPrerequisites() {


  const requiredItems = [

    {
      id:
        "kunai",

      name:
        "Kunai"
    },

    {
      id:
        "shuriken_set",

      name:
        "Shuriken Set"
    },

    {
      id:
        "ninja_wire",

      name:
        "Ninja Wire"
    }

  ];


  requiredItems.forEach(
    requiredItem => {


      const alreadyOwned =
        playerData.inventory.some(
          item =>
            item &&
            item.id ===
              requiredItem.id
        );


      if (
        alreadyOwned
      ) {

        return;
      }


      addItemToInventory(
        requiredItem
      );
    }
  );


  savePlayerData();


  return requiredItems.map(
    requiredItem => {


      const item =
        playerData.inventory.find(
          inventoryItem =>
            inventoryItem &&
            inventoryItem.id ===
              requiredItem.id
        ) ||
        null;


      return {

        itemId:
          requiredItem.id,

        instanceId:
          item &&
          item.instanceId
            ? item.instanceId
            : null

      };
    }
  );
}


