// =========================================================
// BRICK 339 — PERSISTENT BATTLE POUCH PREPARATION
// =========================================================
//
// Persistent Inventory remains the quantity authority.
//
// This record stores only which Item stacks are PREPARED for
// Battle. It does not copy quantities and is not a second
// inventory.
//
// Maximum prepared stack identities: 3.
//
// =========================================================

const BATTLE_POUCH_CAPACITY =
  3;


function normalizeBattlePouchSelection(
  savedBattlePouch
) {


  const sourceIds =
    Array.isArray(
      savedBattlePouch
    )

      ? savedBattlePouch

      : (
          savedBattlePouch &&
          Array.isArray(
            savedBattlePouch.itemIds
          )

            ? savedBattlePouch.itemIds

            : []
        );


  const itemIds =
    [];


  sourceIds.forEach(
    itemId => {


      if (
        itemIds.length >=
          BATTLE_POUCH_CAPACITY
      ) {

        return;
      }


      if (
        typeof itemId !==
          "string" ||
        itemIds.includes(
          itemId
        )
      ) {

        return;
      }


      const definition =
        getItemDefinition(
          itemId
        );


      if (
        !definition ||
        definition.battleConsumable !==
          true
      ) {

        return;
      }


      itemIds.push(
        itemId
      );
    }
  );


  return {

    itemIds:
      itemIds

  };
}


// BRICK 369 — EXPLICIT CHARACTER OWNERSHIP AUTHORITY
// BRICK 370 — ALPHA OWNERSHIP SEED / SAVE MIGRATION
// BRICK 371 — CLAN OWNERSHIP CONSUMER
// BRICK 372 — DEVELOPMENT-PILOT FLAG DECOUPLING
// =========================================================
//
// Registry presence != ownership != team assignment != Battle
// deployment. playerData.characterOwnership owns acquisition
// truth; playerData.clan owns only six-slot formation/favourites.
//
// =========================================================

const CLAN_TEAM_SLOT_COUNT = 6;

const DEFAULT_ALPHA_OWNED_CHARACTER_REGISTRY_IDS = [
  "kage_naruto",
  "jonin_sasuke",
  "sannin_sakura",
  "teen_nagato",
  "academy_hinata",
  "academy_izuno",
  "academy_mirai",
  "academy_menma",
  "academy_kushina"
];

// =========================================================
// BRICK 545 — FRESH ONBOARDING HAS NO AUTO-ROSTER
// BRICK 546 — LEGACY NINE-SEED NON-DESTRUCTIVE MIGRATION BOUNDARY
// =========================================================
const FRESH_ALPHA_OWNED_CHARACTER_REGISTRY_IDS = [];
const LEGACY_ALPHA_SEED_CHARACTER_REGISTRY_IDS = [...DEFAULT_ALPHA_OWNED_CHARACTER_REGISTRY_IDS];

let characterOwnershipRuntimeAuthority = { ownedRegistryIds:[] };

function createDefaultCharacterOwnershipState() {
  return { ownedRegistryIds:[...FRESH_ALPHA_OWNED_CHARACTER_REGISTRY_IDS] };
}

function normalizeCharacterOwnershipState(savedOwnership) {
  const sourceIds = savedOwnership && Array.isArray(savedOwnership.ownedRegistryIds)
    ? savedOwnership.ownedRegistryIds
    : [];
  return {
    ownedRegistryIds:[...new Set(sourceIds.filter(registryId =>
      typeof registryId === "string" && !!getCharacterRegistryEntry(registryId)
    ))]
  };
}

function setCharacterOwnershipRuntimeAuthority(state) {
  characterOwnershipRuntimeAuthority = normalizeCharacterOwnershipState(state);
  return characterOwnershipRuntimeAuthority;
}

function isCharacterRegistryOwned(registryId, ownershipState = characterOwnershipRuntimeAuthority) {
  return !!(
    registryId && ownershipState && Array.isArray(ownershipState.ownedRegistryIds) &&
    ownershipState.ownedRegistryIds.includes(registryId)
  );
}

function isRuntimeCharacterOwned(character, ownershipState = characterOwnershipRuntimeAuthority) {
  return !!character && isCharacterRegistryOwned(getCharacterRegistryId(character), ownershipState);
}

// =========================================================
// BRICK 420 — ACQUISITION-SAFE OWNERSHIP MUTATION API
// =========================================================

function grantCharacterRegistryOwnership(registryId) {
  if (!getCharacterRegistryEntry(registryId)) return {success:false,reason:"character_registry_missing"};
  if (!playerData.characterOwnership) playerData.characterOwnership=createDefaultCharacterOwnershipState();
  const ids=playerData.characterOwnership.ownedRegistryIds;
  const changed=!ids.includes(registryId);
  if (changed) ids.push(registryId);
  setCharacterOwnershipRuntimeAuthority(playerData.characterOwnership);
  savePlayerData();
  return {success:true,changed,registryId,runtimeCharacterId:(getRuntimeCharacterByRegistryId(registryId)||{}).id||null};
}

function revokeCharacterRegistryOwnership(registryId) {
  if (!playerData.characterOwnership || !Array.isArray(playerData.characterOwnership.ownedRegistryIds)) return {success:false,reason:"ownership_state_missing"};
  const before=playerData.characterOwnership.ownedRegistryIds.length;
  playerData.characterOwnership.ownedRegistryIds=playerData.characterOwnership.ownedRegistryIds.filter(id=>id!==registryId);
  const runtime=getRuntimeCharacterByRegistryId(registryId);
  if (runtime && playerData.clan) {
    playerData.clan.teamSlots=(playerData.clan.teamSlots||[]).map(id=>id===runtime.id?null:id);
    playerData.clan.favoriteIds=(playerData.clan.favoriteIds||[]).filter(id=>id!==runtime.id);
  }
  setCharacterOwnershipRuntimeAuthority(playerData.characterOwnership);
  playerData.clan=normalizeClanManagementState(playerData.clan,playerData.characterOwnership);
  savePlayerData();
  return {success:true,changed:before!==playerData.characterOwnership.ownedRegistryIds.length,registryId};
}

// =========================================================
// BRICK 536 — ACQUISITION STATE SCHEMA
// BRICK 537 — OWNEDCHARACTER IDENTITY BRIDGE
// BRICK 538 — ACQUISITIONRECORD IDEMPOTENCY
// =========================================================
const CHRONICLE_ORIGIN_VARIANT_IDS = [
  "academy_hinata",
  "academy_izuno",
  "academy_mirai",
  "academy_menma",
  "academy_kushina"
];

function createOwnedCharacterIdForVariant(variantId) {
  return variantId&&getCharacterRegistryEntry(variantId)?`owned_character_${variantId}`:null;
}

function createAcquisitionRecordKey(definition) {
  if (!definition||!definition.variantId||!definition.route||!definition.sourceEventId) return null;
  return [definition.route,definition.sourceEventId,definition.variantId].join("::");
}

function createDefaultAcquisitionState() {
  return {
    records:[],
    processedRecordKeys:[],
    ownedCharactersByVariantId:{},
    chronicleOriginVariantId:null,
    chronicleOriginOwnedCharacterId:null,
    ninjaIdentityVariantId:null,
    ninjaIdentityOwnedCharacterId:null,
    ninjaIdentityLocked:false,
    onboardingStatus:"chronicle_origin_pending",
    formalRankProgressionByOwnedCharacterId:{},
    firstTeamFormation:{ unlocked:false, promotionEvidenceIds:[], availableCandidateVariantIds:[] },
    joninLeadershipAssignment:null,
    migration:{ source:null, preservedVariantIds:[], identitySelectionRequired:false }
  };
}

function ensureOwnedCharacterRecord(acquisitionState, variantId, acquisitionRecordId=null) {
  if (!acquisitionState||!getCharacterRegistryEntry(variantId)) return null;
  const existing=acquisitionState.ownedCharactersByVariantId[variantId];
  const ownedCharacterId=createOwnedCharacterIdForVariant(variantId);
  const runtime=getRuntimeCharacterByRegistryId(variantId);
  const record=existing&&typeof existing==="object"?existing:{
    ownedCharacterId,
    variantId,
    progressionCharacterId:runtime?runtime.id:variantId,
    acquisitionRecordIds:[]
  };
  record.ownedCharacterId=ownedCharacterId;
  record.variantId=variantId;
  if (!Array.isArray(record.acquisitionRecordIds)) record.acquisitionRecordIds=[];
  if (acquisitionRecordId&&!record.acquisitionRecordIds.includes(acquisitionRecordId)) record.acquisitionRecordIds.push(acquisitionRecordId);
  acquisitionState.ownedCharactersByVariantId[variantId]=record;
  return record;
}

function normalizeAcquisitionState(savedState, ownershipState, options={}) {
  const defaults=createDefaultAcquisitionState();
  const source=savedState&&typeof savedState==="object"?savedState:{};
  const state={
    ...defaults,
    records:Array.isArray(source.records)?source.records.filter(record=>record&&record.recordId&&record.variantId):[],
    processedRecordKeys:Array.isArray(source.processedRecordKeys)?[...new Set(source.processedRecordKeys.filter(Boolean))]:[],
    ownedCharactersByVariantId:source.ownedCharactersByVariantId&&typeof source.ownedCharactersByVariantId==="object"?cloneProgressionData(source.ownedCharactersByVariantId):{},
    chronicleOriginVariantId:source.chronicleOriginVariantId||null,
    chronicleOriginOwnedCharacterId:source.chronicleOriginOwnedCharacterId||null,
    ninjaIdentityVariantId:source.ninjaIdentityVariantId||null,
    ninjaIdentityOwnedCharacterId:source.ninjaIdentityOwnedCharacterId||null,
    ninjaIdentityLocked:source.ninjaIdentityLocked===true,
    onboardingStatus:typeof source.onboardingStatus==="string"?source.onboardingStatus:defaults.onboardingStatus,
    formalRankProgressionByOwnedCharacterId:source.formalRankProgressionByOwnedCharacterId&&typeof source.formalRankProgressionByOwnedCharacterId==="object"?cloneProgressionData(source.formalRankProgressionByOwnedCharacterId):{},
    firstTeamFormation:source.firstTeamFormation&&typeof source.firstTeamFormation==="object"?{
      unlocked:source.firstTeamFormation.unlocked===true,
      promotionEvidenceIds:Array.isArray(source.firstTeamFormation.promotionEvidenceIds)?[...new Set(source.firstTeamFormation.promotionEvidenceIds.filter(Boolean))]:[],
      availableCandidateVariantIds:Array.isArray(source.firstTeamFormation.availableCandidateVariantIds)?[...new Set(source.firstTeamFormation.availableCandidateVariantIds.filter(id=>!!getCharacterRegistryEntry(id)))]:[]
    }:defaults.firstTeamFormation,
    joninLeadershipAssignment:source.joninLeadershipAssignment?cloneProgressionData(source.joninLeadershipAssignment):null,
    migration:source.migration&&typeof source.migration==="object"?cloneProgressionData(source.migration):defaults.migration
  };
  const ownedIds=ownershipState&&Array.isArray(ownershipState.ownedRegistryIds)?ownershipState.ownedRegistryIds:[];
  ownedIds.forEach(variantId=>ensureOwnedCharacterRecord(state,variantId));
  if (options.legacySeedMigration===true&&ownedIds.length>0&&state.records.length===0) {
    state.migration={source:"pre_acquisition_alpha_seed",preservedVariantIds:[...ownedIds],identitySelectionRequired:!state.ninjaIdentityVariantId};
    ownedIds.forEach(variantId=>{
      const key=`migration::pre_acquisition_alpha_seed:${variantId}::${variantId}`;
      const recordId=`acquisition_${key.replace(/[^a-zA-Z0-9_:-]/g,"_")}`;
      const record={recordId,recordKey:key,variantId,route:"migration",sourceEventId:`pre_acquisition_alpha_seed:${variantId}`,timestamp:null,context:{},provenance:{source:"pre_acquisition_alpha_seed"},linkedChronicleEvidenceIds:[],duplicate:false,duplicateCompensationResult:null};
      state.records.push(record); state.processedRecordKeys.push(key); ensureOwnedCharacterRecord(state,variantId,recordId);
    });
    state.processedRecordKeys=[...new Set(state.processedRecordKeys)];
    state.onboardingStatus=state.ninjaIdentityVariantId?"migrated":"identity_selection_pending";
  }
  return state;
}

function ensurePlayerAcquisitionState() {
  if (!playerData.acquisition) playerData.acquisition=normalizeAcquisitionState(null,playerData.characterOwnership||characterOwnershipRuntimeAuthority);
  return playerData.acquisition;
}

function getOwnedCharacterRecordByVariantId(variantId) {
  return ensurePlayerAcquisitionState().ownedCharactersByVariantId[variantId]||null;
}

function getOwnedCharacterRecordById(ownedCharacterId) {
  return Object.values(ensurePlayerAcquisitionState().ownedCharactersByVariantId).find(record=>record&&record.ownedCharacterId===ownedCharacterId)||null;
}

// =========================================================
// BRICK 539 — FIRST ACQUISITION OWNERSHIP COMMIT
// BRICK 540 — DUPLICATE ACQUISITION PROVENANCE
// BRICK 541 — AUTHORED DUPLICATE-COMPENSATION RECORD
// BRICK 641 — ACTIVE KONOHA PROVENANCE SCOPE ADDRESSABILITY
// =========================================================
const ACTIVE_KONOHA_CONTINUITY_ID="active_konoha";
const HISTORY_SCOPE_KINDS=Object.freeze([
  "representation_source_provenance",
  "active_konoha_chronicle_occurrence",
  "shared_history",
  "observer_knowledge",
  "world_chronology"
]);

function createHistoryScopeAddress(kind,details={}) {
  if (!HISTORY_SCOPE_KINDS.includes(kind)) return null;
  return {kind,continuityId:kind==="active_konoha_chronicle_occurrence"?ACTIVE_KONOHA_CONTINUITY_ID:(details.continuityId||null),...cloneProgressionData(details)};
}

function getHistoryScopeAddress(record) {
  if (!record||typeof record!=="object") return null;
  if (record.historyScope&&HISTORY_SCOPE_KINDS.includes(record.historyScope.kind)) return cloneProgressionData(record.historyScope);
  if (record.provenance&&record.provenance.historyScope&&HISTORY_SCOPE_KINDS.includes(record.provenance.historyScope.kind)) return cloneProgressionData(record.provenance.historyScope);
  if (record.route==="migration"||(record.provenance&&record.provenance.source==="pre_acquisition_alpha_seed")) return createHistoryScopeAddress("representation_source_provenance",{source:"pre_acquisition_alpha_seed"});
  return null;
}

function createRepresentationSourceProvenanceFact(definition={}) {
  if (!definition.factId||!definition.representationId) return null;
  return {
    factId:definition.factId,
    representationId:definition.representationId,
    relatedRepresentationIds:Array.isArray(definition.relatedRepresentationIds)?[...new Set(definition.relatedRepresentationIds.filter(Boolean))]:[],
    data:definition.data?cloneProgressionData(definition.data):{},
    historyScope:createHistoryScopeAddress("representation_source_provenance",{sourceContextId:definition.sourceContextId||null}),
    importedIntoActiveKonoha:false
  };
}

function scopedHistoryRecordCanEstablish(record,kind,options={}) {
  const scope=getHistoryScopeAddress(record);
  if (!scope) return false;
  if (scope.kind===kind) return true;
  if (kind==="active_konoha_chronicle_occurrence"&&options.explicitRepresentationImportContract===true) return true;
  return false;
}

function sourceProvenanceCreatesLocalHistoryAutomatically(record) {
  return scopedHistoryRecordCanEstablish(record,"active_konoha_chronicle_occurrence",{explicitRepresentationImportContract:false});
}

function runActiveKonohaProvenanceScopeDiagnostics() {
  const eventCountBefore=Array.isArray(activityHistory)?activityHistory.length:0;
  const sourceFact=createRepresentationSourceProvenanceFact({factId:"diagnostic_kurenai_mirai_source_fact",representationId:"academy_kurenai",relatedRepresentationIds:["academy_mirai"],sourceContextId:"source_context_diagnostic"});
  const result={
    sourceFactRetrievable:!!sourceFact&&getHistoryScopeAddress(sourceFact).kind==="representation_source_provenance",
    coexistenceDoesNotAppendActiveKonohaOccurrence:!!sourceFact&&!sourceProvenanceCreatesLocalHistoryAutomatically(sourceFact)&&(Array.isArray(activityHistory)?activityHistory.length:0)===eventCountBefore,
    coexistenceDoesNotCreateSharedHistory:!!sourceFact&&!scopedHistoryRecordCanEstablish(sourceFact,"shared_history"),
    coexistenceDoesNotCreateReciprocalMemory:!!sourceFact&&!Object.prototype.hasOwnProperty.call(sourceFact,"reciprocalMemory"),
    coexistenceDoesNotGrantObserverKnowledge:!!sourceFact&&!scopedHistoryRecordCanEstablish(sourceFact,"observer_knowledge"),
    representationStageDoesNotWriteWorldChronology:!!sourceFact&&!scopedHistoryRecordCanEstablish(sourceFact,"world_chronology"),
    crossGenerationDoesNotCreateTemporalAnomaly:!!sourceFact&&!Object.prototype.hasOwnProperty.call(sourceFact,"temporalAnomaly"),
    lineageDoesNotCreateRelationshipEvidence:!!sourceFact&&!Object.prototype.hasOwnProperty.call(sourceFact,"relationshipEvidence"),
    explicitImportCanAuthoriseLocalBoundary:!!sourceFact&&scopedHistoryRecordCanEstablish(sourceFact,"active_konoha_chronicle_occurrence",{explicitRepresentationImportContract:true})
  };
  result.pass=Object.values(result).every(value=>value===true);
  console.table(result);
  return result;
}

function commitCharacterAcquisition(definition) {
  if (!definition||!getCharacterRegistryEntry(definition.variantId)) return {success:false,reason:"character_registry_missing"};
  const recordKey=createAcquisitionRecordKey(definition);
  if (!recordKey) return {success:false,reason:"acquisition_identity_incomplete"};
  const state=ensurePlayerAcquisitionState();
  const existing=state.records.find(record=>record&&record.recordKey===recordKey);
  if (existing) return {success:true,idempotent:true,record:existing,ownedCharacter:getOwnedCharacterRecordByVariantId(definition.variantId)};
  const alreadyOwned=isCharacterRegistryOwned(definition.variantId);
  if (!alreadyOwned) {
    const grant=grantCharacterRegistryOwnership(definition.variantId);
    if (!grant.success) return grant;
  }
  const recordId=`acquisition_${state.records.length+1}_${Date.now()}`;
  const record={
    recordId,recordKey,variantId:definition.variantId,route:definition.route,sourceEventId:definition.sourceEventId,
    timestamp:definition.timestamp||Date.now(),context:definition.context?cloneProgressionData(definition.context):{},
    historyScope:createHistoryScopeAddress("active_konoha_chronicle_occurrence",{continuityId:ACTIVE_KONOHA_CONTINUITY_ID,occurrenceType:"character_acquisition"}),
    provenance:definition.provenance?cloneProgressionData(definition.provenance):{},
    linkedChronicleEvidenceIds:Array.isArray(definition.linkedChronicleEvidenceIds)?[...new Set(definition.linkedChronicleEvidenceIds.filter(Boolean))]:[],
    duplicate:alreadyOwned,
    duplicateCompensationResult:alreadyOwned&&definition.duplicateCompensationResult?cloneProgressionData(definition.duplicateCompensationResult):null
  };
  state.records.push(record); state.processedRecordKeys.push(recordKey); state.processedRecordKeys=[...new Set(state.processedRecordKeys)];
  const ownedCharacter=ensureOwnedCharacterRecord(state,definition.variantId,recordId);
  playerData.clan=normalizeClanManagementState(playerData.clan,playerData.characterOwnership);
  savePlayerData();
  return {success:true,idempotent:false,duplicate:alreadyOwned,record,ownedCharacter};
}

// =========================================================
// BRICK 542 — LINKED GRANT BUNDLE TRANSACTION
// =========================================================
function commitAcquisitionGrantBundle(bundle) {
  if (!bundle||!bundle.bundleId) return {success:false,reason:"grant_bundle_identity_missing"};
  const snapshot=cloneProgressionData(playerData);
  try {
    const results={characters:[],entities:[],attachments:[]};
    (bundle.characterGrants||[]).forEach(grant=>{const r=commitCharacterAcquisition({...grant,sourceEventId:grant.sourceEventId||bundle.bundleId});if(!r.success)throw new Error(r.reason||"character_grant_failed");results.characters.push(r);});
    (bundle.entityGrantIds||[]).forEach(entityId=>{const r=grantEntityOwnership(entityId);if(!r.success)throw new Error(r.reason||"entity_grant_failed");results.entities.push(r);});
    (bundle.attachedSummonAssignments||[]).forEach(assignment=>{const ok=attachEntitySummonToCharacter(assignment.characterId,assignment.entityId);if(!ok)throw new Error("summon_assignment_failed");results.attachments.push({...assignment});});
    savePlayerData();
    return {success:true,bundleId:bundle.bundleId,results};
  } catch (error) {
    playerData=snapshot;
    setCharacterOwnershipRuntimeAuthority(playerData.characterOwnership||createDefaultCharacterOwnershipState());
    savePlayerData();
    return {success:false,reason:"grant_bundle_rolled_back",error:String(error&&error.message||error)};
  }
}

// =========================================================
// BRICK 543 — SINGLE CHRONICLE-ORIGIN CONTRACT
// BRICK 544 — NINJA ID IDENTITY / ALPHA LOCK
// =========================================================
function selectChronicleOrigin(variantId, sourceEventId="onboarding_chronicle_origin_confirmation") {
  const state=ensurePlayerAcquisitionState();
  if (!CHRONICLE_ORIGIN_VARIANT_IDS.includes(variantId)) return {success:false,reason:"invalid_chronicle_origin"};
  if (state.chronicleOriginVariantId) return {success:false,reason:"chronicle_origin_already_confirmed"};
  const acquisition=commitCharacterAcquisition({variantId,route:"chronicle_origin",sourceEventId,context:{phase:"academy_opening"},provenance:{authority:"player_onboarding"}});
  if (!acquisition.success) return acquisition;
  const ownedCharacter=acquisition.ownedCharacter;
  state.chronicleOriginVariantId=variantId;
  state.chronicleOriginOwnedCharacterId=ownedCharacter.ownedCharacterId;
  state.ninjaIdentityVariantId=variantId;
  state.ninjaIdentityOwnedCharacterId=ownedCharacter.ownedCharacterId;
  state.ninjaIdentityLocked=true;
  state.onboardingStatus="academy_chronicle";
  const runtime=getRuntimeCharacterByRegistryId(variantId);
  if (runtime) {
    playerData.clan=normalizeClanManagementState({teamSlots:[runtime.id,null,null,null,null,null],favoriteIds:(playerData.clan&&playerData.clan.favoriteIds)||[]},playerData.characterOwnership);
  }
  savePlayerData();
  return {success:true,variantId,ownedCharacterId:ownedCharacter.ownedCharacterId,ninjaIdentityLocked:true};
}

function getNinjaIdentityRecord() {
  const state=ensurePlayerAcquisitionState();
  return {variantId:state.ninjaIdentityVariantId,ownedCharacterId:state.ninjaIdentityOwnedCharacterId,locked:state.ninjaIdentityLocked===true};
}

// =========================================================
// BRICK 547 — GENIN PROMOTION PROGRESSION RECORD
// BRICK 548 — FIRST TEAM FORMATION UNLOCK / CANDIDATE CONTRACT
// =========================================================
function recordOwnedCharacterGeninPromotion(ownedCharacterId, evidenceIds=[]) {
  const state=ensurePlayerAcquisitionState();
  const owned=getOwnedCharacterRecordById(ownedCharacterId);
  if (!owned) return {success:false,reason:"owned_character_missing"};
  const ids=Array.isArray(evidenceIds)?[...new Set(evidenceIds.filter(Boolean))]:[];
  state.formalRankProgressionByOwnedCharacterId[ownedCharacterId]={formalRank:"genin",promotedAt:Date.now(),promotionEvidenceIds:ids};
  state.firstTeamFormation.unlocked=true;
  state.firstTeamFormation.promotionEvidenceIds=[...new Set([...(state.firstTeamFormation.promotionEvidenceIds||[]),...ids])];
  state.onboardingStatus="first_team_formation_available";
  savePlayerData();
  return {success:true,ownedCharacterId,formalRank:"genin",firstTeamFormationUnlocked:true};
}

function setFirstTeamFormationAvailableCandidates(variantIds) {
  const state=ensurePlayerAcquisitionState();
  state.firstTeamFormation.availableCandidateVariantIds=Array.isArray(variantIds)?[...new Set(variantIds.filter(id=>!!getCharacterRegistryEntry(id)))]:[];
  savePlayerData();
  return [...state.firstTeamFormation.availableCandidateVariantIds];
}

function getFirstTeamFormationCandidateVariantIds() {
  const state=ensurePlayerAcquisitionState();
  if (state.firstTeamFormation.unlocked!==true) return [];
  const owned=playerData.characterOwnership&&Array.isArray(playerData.characterOwnership.ownedRegistryIds)?playerData.characterOwnership.ownedRegistryIds:[];
  return [...new Set([...owned,...(state.firstTeamFormation.availableCandidateVariantIds||[])])];
}

function setJoninLeadershipAssignment(assignment) {
  const state=ensurePlayerAcquisitionState();
  state.joninLeadershipAssignment=assignment?cloneProgressionData(assignment):null;
  savePlayerData();
  return state.joninLeadershipAssignment;
}

// =========================================================
// BRICK 549 — ACQUISITION MASTER DIAGNOSTIC
// =========================================================
function runAcquisitionV1Diagnostics() {
  const state=ensurePlayerAcquisitionState();
  const ownedIds=playerData.characterOwnership&&Array.isArray(playerData.characterOwnership.ownedRegistryIds)?playerData.characterOwnership.ownedRegistryIds:[];
  const result={
    onePersistentOwnedRecordPerVariant:Object.keys(state.ownedCharactersByVariantId).every(variantId=>state.ownedCharactersByVariantId[variantId].ownedCharacterId===createOwnedCharacterIdForVariant(variantId)),
    ownershipSeparateFromIdentity:typeof state.ninjaIdentityVariantId!=="undefined"&&Array.isArray(ownedIds),
    originChoicesExactlyFive:CHRONICLE_ORIGIN_VARIANT_IDS.length===5&&new Set(CHRONICLE_ORIGIN_VARIANT_IDS).size===5,
    noFreshAutoRoster:createDefaultCharacterOwnershipState().ownedRegistryIds.length===0,
    noFreshAutoEntityGrant:createDefaultPlayerEntityState().ownedEntityIds.length===0,
    firstTeamFormationSeparate:state.firstTeamFormation&&typeof state.firstTeamFormation.unlocked==="boolean",
    joninAssignmentSeparate:Object.prototype.hasOwnProperty.call(state,"joninLeadershipAssignment")
  };
  result.pass=Object.values(result).every(value=>value===true);
  return result;
}

function getClanManageableRosterCharacters(ownershipState = characterOwnershipRuntimeAuthority) {
  return playerTeam.filter(character =>
    character && character.id && isRuntimeCharacterOwned(character, ownershipState)
  );
}

function createDefaultClanManagementState(ownershipState = characterOwnershipRuntimeAuthority) {
  const defaultIds = getClanManageableRosterCharacters(ownershipState)
    .slice(0, CLAN_TEAM_SLOT_COUNT)
    .map(character => character.id);
  return {
    teamSlots: Array.from({length:CLAN_TEAM_SLOT_COUNT}, (_, index) => defaultIds[index] || null),
    favoriteIds: []
  };
}

function normalizeClanManagementState(savedClan, ownershipState = characterOwnershipRuntimeAuthority) {
  const defaults = createDefaultClanManagementState(ownershipState);
  if (!savedClan || typeof savedClan !== "object") return defaults;
  const manageableIds = new Set(getClanManageableRosterCharacters(ownershipState).map(character => character.id));
  const rawSlots = Array.isArray(savedClan.teamSlots)
    ? savedClan.teamSlots
    : (Array.isArray(savedClan.teamIds) ? savedClan.teamIds : null);
  const teamSlots = [];
  const seen = new Set();
  if (rawSlots) {
    for (let index=0; index<CLAN_TEAM_SLOT_COUNT; index+=1) {
      const characterId = typeof rawSlots[index] === "string" ? rawSlots[index] : null;
      const validId = characterId && manageableIds.has(characterId) && !seen.has(characterId) ? characterId : null;
      teamSlots.push(validId);
      if (validId) seen.add(validId);
    }
  } else {
    teamSlots.push(...defaults.teamSlots);
  }
  const favoriteIds = Array.isArray(savedClan.favoriteIds)
    ? [...new Set(savedClan.favoriteIds.filter(characterId => typeof characterId === "string" && manageableIds.has(characterId)))]
    : [];
  return { teamSlots, favoriteIds };
}



// BRICK 373 — ENTITY CURRENT-STATE SAVE AUTHORITY
// BRICK 374 — ATTACHED SUMMON SAVE AUTHORITY
// BRICK 375 — EXACT-INSTANCE WEAPON ACCLIMATION SAVE AUTHORITY
// =========================================================

function createDefaultEntityCurrentStats() {
  const currentStatsByEntityId = {};
  Object.values(entityRegistry).forEach(entity => {
    if (entity && entity.baseStats) currentStatsByEntityId[entity.id] = cloneCanonicalSevenStats(entity.baseStats);
  });
  return currentStatsByEntityId;
}

function createDefaultPlayerEntityState(options = {}) {
  const legacySeed = options.legacySeedMigration === true;
  return {
    ownedEntityIds: legacySeed ? ["menma_nine_tails"] : [],
    currentStatsByEntityId: createDefaultEntityCurrentStats(),
    attachedSummonByCharacterRegistryId: legacySeed ? { academy_menma:"menma_nine_tails" } : {}
  };
}

function getEntityCurrentStats(entityId) {
  const definition = getEntityDefinition(entityId);
  const saved = playerData && playerData.entities && playerData.entities.currentStatsByEntityId
    ? playerData.entities.currentStatsByEntityId[entityId]
    : null;
  return cloneCanonicalSevenStats(saved || (definition ? definition.baseStats : null));
}

function calculateEntityCurrentPL(entityId) {
  const definition = getEntityDefinition(entityId);
  if (!definition || !definition.baseStats) return null;
  return Math.round(calculateRawPLFromStats(getEntityCurrentStats(entityId)));
}

// =========================================================
// BRICK 421 — ENTITY OWNERSHIP / PERMANENT STAT DEVELOPMENT API
// =========================================================

function grantEntityOwnership(entityId) {
  const entity=getEntityDefinition(entityId);
  if (!entity || !entity.baseStats) return {success:false,reason:"entity_registry_missing_or_reserved"};
  if (!playerData.entities) playerData.entities=createDefaultPlayerEntityState();
  const changed=!playerData.entities.ownedEntityIds.includes(entityId);
  if (changed) playerData.entities.ownedEntityIds.push(entityId);
  if (!playerData.entities.currentStatsByEntityId[entityId]) playerData.entities.currentStatsByEntityId[entityId]=cloneCanonicalSevenStats(entity.baseStats);
  savePlayerData();
  return {success:true,changed,entityId};
}

function increaseEntityStat(entityId, statName, amount) {
  const validStats=["nin","tai","buki","fuin","kin","gen","stamina"];
  if (!validStats.includes(statName)) return {success:false,reason:"invalid_stat"};
  const entity=getEntityDefinition(entityId);
  if (!entity || !entity.baseStats) return {success:false,reason:"entity_registry_missing"};
  if (!playerData.entities || !playerData.entities.ownedEntityIds.includes(entityId)) return {success:false,reason:"entity_not_owned"};
  const delta=Number(amount)||0;
  if (delta===0) return {success:false,reason:"zero_stat_change"};
  const stats=playerData.entities.currentStatsByEntityId[entityId] || cloneCanonicalSevenStats(entity.baseStats);
  stats[statName]=(Number(stats[statName])||0)+delta;
  playerData.entities.currentStatsByEntityId[entityId]=stats;
  savePlayerData();
  return {success:true,entityId,statName,currentValue:stats[statName],currentPL:calculateEntityCurrentPL(entityId)};
}

function createDefaultPlayerData() {
  const characterOwnership = createDefaultCharacterOwnershipState();
  setCharacterOwnershipRuntimeAuthority(characterOwnership);
  return {
    ryo: 0,
    exp: 0,
    inventory: [],
    battlePouch: normalizeBattlePouchSelection(null),
    characterOwnership: characterOwnership,
    acquisition: createDefaultAcquisitionState(),
    specialistQualifications: createDefaultSpecialistQualificationState(),
    clan: createDefaultClanManagementState(characterOwnership),
    entities: createDefaultPlayerEntityState(),
    weaponAcclimation: {},
    activityHistory: [],
    progression: createDefaultRunProgression(),
    characters: createDefaultCharacterProgression(),
    collections: {
      specialNinja: [],
      bloodlines: []
    }
  };
}


// =========================================================
// NORMALIZE PLAYER COLLECTIONS
// =========================================================

function normalizePlayerCollections(
  savedCollections
) {


  const source =
    savedCollections &&
    typeof savedCollections ===
      "object"

      ? savedCollections

      : {};


  return {

    specialNinja:
      normalizeInheritanceCollection(
        source.specialNinja
      ),

    bloodlines:
      normalizeInheritanceCollection(
        source.bloodlines
      )

  };

}


// =========================================================
// NORMALIZE SAVED RUN PROGRESSION
// =========================================================

function normalizeSavedRunProgression(
  savedProgression
) {


  const defaults =
    createDefaultRunProgression();


  if (
    !savedProgression ||
    typeof savedProgression !==
      "object"
  ) {

    return defaults;

  }


  const currentDifficulty =
    getShinobiDifficulty(
      savedProgression.currentDifficulty
    )
      ? savedProgression.currentDifficulty
      : defaults.currentDifficulty;


  const highestDifficultyUnlocked =
    getShinobiDifficulty(
      savedProgression.highestDifficultyUnlocked
    )
      ? savedProgression.highestDifficultyUnlocked
      : defaults.highestDifficultyUnlocked;


  return {

    currentDifficulty:
      currentDifficulty,

    highestDifficultyUnlocked:
      highestDifficultyUnlocked,

    legacyCycle:
      Math.max(
        0,
        Math.floor(
          Number(
            savedProgression.legacyCycle
          ) || 0
        )
      ),

    completedDifficulties:
      Array.isArray(
        savedProgression.completedDifficulties
      )
        ? savedProgression.completedDifficulties.filter(
            difficultyId =>
              !!getShinobiDifficulty(
                difficultyId
              )
          )
        : [],

    runCompleted:
      savedProgression.runCompleted ===
      true

  };

}

// =========================================================
// NORMALIZE DISCIPLINE PROGRESSION
// =========================================================

function normalizeDisciplineProgression(
  savedProgression
) {


  const defaults =
    createDefaultDisciplineProgression();


  const source =
    savedProgression &&
    typeof savedProgression ===
      "object"
      ? savedProgression
      : {};


  const normalized = {};


  Object.keys(
    defaults
  ).forEach(
    disciplineId => {


      const savedRecord =
        source[
          disciplineId
        ] || {};


      const level =
        Math.max(
          1,
          Math.floor(
            Number(
              savedRecord.level
            ) || 1
          )
        );


      const rawStatLevelApplied =
        savedRecord.statLevelApplied;


      const statLevelApplied =
        Number.isFinite(
          Number(
            rawStatLevelApplied
          )
        )
          ? Math.max(
              1,
              Math.min(
                level,
                Math.floor(
                  Number(
                    rawStatLevelApplied
                  )
                )
              )
            )
          : 1;


      normalized[
        disciplineId
      ] = {

        level:
          level,

        exp:
          Math.max(
            0,
            Number(
              savedRecord.exp
            ) || 0
          ),

        statLevelApplied:
          statLevelApplied

      };

    }
  );


  return normalized;

}


// NORMALIZE SAVED CHARACTER PROGRESSION
// =========================================================

function normalizeSavedCharacterProgression(
  savedCharacters
) {


  const defaults =
    createDefaultCharacterProgression();


  const source =
    savedCharacters &&
    typeof savedCharacters ===
      "object"
      ? savedCharacters
      : {};


  const normalized = {};


  Object.keys(
    defaults
  ).forEach(
    characterId => {


      const defaultCharacter =
        defaults[
          characterId
        ];


      const savedCharacter =
        source[
          characterId
        ] || {};


      const savedStats =
        savedCharacter.stats &&
        typeof savedCharacter.stats ===
          "object"
          ? savedCharacter.stats
          : {};


      const normalizedStats = {
        ...defaultCharacter.stats
      };


      Object.keys(
        normalizedStats
      ).forEach(
        stat => {


          if (
            typeof savedStats[
              stat
            ] ===
              "number"
          ) {

            normalizedStats[
              stat
            ] =
              savedStats[
                stat
              ];

          }

        }
      );


      normalized[
        characterId
      ] = {

        stats:
          normalizedStats,

        permanentPLBonus:
          typeof savedCharacter
            .permanentPLBonus ===
            "number"

            ? savedCharacter
                .permanentPLBonus

            : defaultCharacter
                .permanentPLBonus,

        disciplineProgression:
          normalizeDisciplineProgression(
            savedCharacter
              .disciplineProgression
          ),

        weaponSpecializations:
          savedCharacter
            .weaponSpecializations &&
          typeof savedCharacter
            .weaponSpecializations ===
            "object"

            ? cloneProgressionData(
                savedCharacter
                  .weaponSpecializations
              )

            : cloneProgressionData(
                defaultCharacter
                  .weaponSpecializations
              )

      };

    }
  );


  return normalized;

}


// =========================================================


// =========================================================
// BRICK 376 — ENTITY SAVE NORMALIZATION
// BRICK 377 — ATTACHMENT VALIDATION / MIGRATION
// BRICK 378 — ACCLIMATION MUTUAL-EXCLUSIVITY NORMALIZATION
// =========================================================

function normalizePlayerEntityState(savedEntities, options = {}) {
  const defaults = createDefaultPlayerEntityState(options);
  const source = savedEntities && typeof savedEntities === "object" ? savedEntities : {};
  const ownedEntityIds = Array.isArray(source.ownedEntityIds)
    ? [...new Set(source.ownedEntityIds.filter(entityId => typeof entityId === "string" && !!getEntityDefinition(entityId)))]
    : [...defaults.ownedEntityIds];
  const currentStatsByEntityId = {};
  Object.entries(defaults.currentStatsByEntityId).forEach(([entityId, baseStats]) => {
    const saved = source.currentStatsByEntityId && source.currentStatsByEntityId[entityId];
    const stats = cloneCanonicalSevenStats(baseStats);
    if (saved && typeof saved === "object") {
      Object.keys(stats).forEach(stat => {
        if (typeof saved[stat] === "number" && Number.isFinite(saved[stat])) stats[stat] = saved[stat];
      });
    }
    currentStatsByEntityId[entityId] = stats;
  });
  const attached = {};
  const rawAttached = source.attachedSummonByCharacterRegistryId && typeof source.attachedSummonByCharacterRegistryId === "object"
    ? source.attachedSummonByCharacterRegistryId
    : defaults.attachedSummonByCharacterRegistryId;
  Object.entries(rawAttached).forEach(([registryId, entityId]) => {
    const entity = getEntityDefinition(entityId);
    if (getCharacterRegistryEntry(registryId) && isAttachableSummonEntity(entity)) {
      attached[registryId] = entityId;
    }
  });
  return { ownedEntityIds, currentStatsByEntityId, attachedSummonByCharacterRegistryId: attached };
}

function normalizeWeaponAcclimationState(savedState) {
  const source = savedState && typeof savedState === "object" ? savedState : {};
  const normalized = {};
  Object.entries(source).forEach(([registryId, instanceMap]) => {
    if (!getCharacterRegistryEntry(registryId) || !instanceMap || typeof instanceMap !== "object") return;
    normalized[registryId] = {};
    Object.entries(instanceMap).forEach(([instanceId, record]) => {
      if (!instanceId || !record || typeof record !== "object") return;
      if (record.state === "unfamiliar") {
        normalized[registryId][instanceId] = { state:"unfamiliar", severity:null };
      } else if (record.state === "reacclimating" && ["minor","major","fundamental"].includes(record.severity)) {
        normalized[registryId][instanceId] = { state:"reacclimating", severity:record.severity };
      }
    });
  });
  return normalized;
}



// =========================================================
// LOAD PLAYER DATA
// =========================================================

// =========================================================
// BRICK 379 — OWNERSHIP-AWARE SAVE LOAD
// BRICK 380 — ENTITY / ACCLIMATION SAVE LOAD
// =========================================================

function loadPlayerData() {
  const savedData = localStorage.getItem(PLAYER_SAVE_KEY);
  if (!savedData) {
    console.log("No existing player save found.");
    const defaults = createDefaultPlayerData();
    setCharacterOwnershipRuntimeAuthority(defaults.characterOwnership);
    return defaults;
  }
  try {
    const parsedData = JSON.parse(savedData);
    console.log("Player save loaded:", parsedData);
    const legacySeedMigration = !parsedData.acquisition;
    const characterOwnership = normalizeCharacterOwnershipState(
      parsedData.characterOwnership || (legacySeedMigration ? {ownedRegistryIds:[...LEGACY_ALPHA_SEED_CHARACTER_REGISTRY_IDS]} : null)
    );
    setCharacterOwnershipRuntimeAuthority(characterOwnership);
    const acquisition = normalizeAcquisitionState(parsedData.acquisition,characterOwnership,{legacySeedMigration});
    return {
      ryo: Number(parsedData.ryo) || 0,
      exp: Number(parsedData.exp) || 0,
      inventory: Array.isArray(parsedData.inventory) ? parsedData.inventory : [],
      battlePouch: normalizeBattlePouchSelection(parsedData.battlePouch),
      characterOwnership: characterOwnership,
      acquisition: acquisition,
      specialistQualifications: normalizeSpecialistQualificationState(parsedData.specialistQualifications),
      clan: normalizeClanManagementState(parsedData.clan, characterOwnership),
      entities: normalizePlayerEntityState(parsedData.entities,{legacySeedMigration}),
      weaponAcclimation: normalizeWeaponAcclimationState(parsedData.weaponAcclimation),
      activityHistory: Array.isArray(parsedData.activityHistory) ? parsedData.activityHistory : [],
      progression: normalizeSavedRunProgression(parsedData.progression),
      characters: normalizeSavedCharacterProgression(parsedData.characters),
      collections: normalizePlayerCollections(parsedData.collections)
    };
  } catch (error) {
    console.log("Player save could not be loaded:", error);
    const defaults = createDefaultPlayerData();
    setCharacterOwnershipRuntimeAuthority(defaults.characterOwnership);
    return defaults;
  }
}



// =========================================================
// ACTIVE PLAYER DATA
// =========================================================

let playerData =
  loadPlayerData();



// =========================================================
// RESTORE CHARACTER PROGRESSION FROM SAVE
// =========================================================
//
// Canonical PL migration:
//
// Old saves stored absolute character.stats values.
//
// Base Stats have now been recalibrated for the universal
// Peak / Core / Breadth PL model.
//
// To preserve player training without restoring obsolete
// stat baselines:
//
// - discipline level is preserved
// - discipline EXP is preserved
// - statLevelApplied is preserved
// - weapon specialisation is preserved
// - natural stats are rebuilt from NEW Base Stats
//
// =========================================================

function syncCharacterProgressionFromSave() {


  if (
    !playerData.characters ||
    typeof playerData.characters !==
      "object"
  ) {

    playerData.characters =
      createDefaultCharacterProgression();

  }


  playerTeam.forEach(
    character => {


      const savedCharacter =
        playerData.characters[
          character.id
        ];


      if (!savedCharacter) {

        return;

      }


      // =========================================
      // RESTORE DISCIPLINE PROGRESSION FIRST
      // =========================================

      character.disciplineProgression =
        normalizeDisciplineProgression(
          savedCharacter
            .disciplineProgression
        );


      // =========================================
      // REBUILD NATURAL CURRENT STATS
      // =========================================
      //
      // Base Stat
      // +
      // already-earned discipline stat levels.
      //
      // Old absolute saved stats are deliberately
      // not restored.
      // =========================================

      Object.keys(
        character.baseStats
      ).forEach(
        stat => {


          const progression =
            character
              .disciplineProgression[
                stat
              ];


          const appliedLevel =
            progression
              ? Math.max(
                  1,
                  Math.floor(
                    Number(
                      progression
                        .statLevelApplied
                    ) || 1
                  )
                )
              : 1;


          const levelsAboveBase =
            Math.max(
              0,
              appliedLevel - 1
            );


          const statGainPerLevel =
            getDisciplineStatGainPerLevel(
              stat
            );


          character.stats[
            stat
          ] =
            (
              Number(
                character.baseStats[
                  stat
                ]
              ) || 0
            )
            +
            (
              levelsAboveBase *
              statGainPerLevel
            );

        }
      );


      // =========================================
      // LEGACY DIRECT PL BONUS RETIRED
      // =========================================

      character.permanentPLBonus =
        0;


      // =========================================
      // RESTORE WEAPON SPECIALIZATIONS
      // =========================================

      character.weaponSpecializations =
        cloneProgressionData(
          savedCharacter
            .weaponSpecializations
        );

    }
  );


  console.log(
    "Character progression restored against canonical Base Stats."
  );

}


// =========================================================
// COPY RUNTIME CHARACTER PROGRESSION TO SAVE
// =========================================================

function syncRuntimeProgressionToPlayerData() {


  if (
    !playerData.characters ||
    typeof playerData.characters !==
      "object"
  ) {

    playerData.characters = {};

  }


  playerTeam.forEach(
    character => {


      playerData.characters[
        character.id
      ] = {

        stats: {
          ...character.stats
        },

        permanentPLBonus:
          Number(
            character.permanentPLBonus
          ) || 0,

        disciplineProgression:
          normalizeDisciplineProgression(
            character
              .disciplineProgression
          ),

        weaponSpecializations:
          cloneProgressionData(
            character.weaponSpecializations
          )

      };

    }
  );

}

// =========================================================
// APPLY SAVED CHARACTER PROGRESSION NOW
// =========================================================

syncCharacterProgressionFromSave();





// =========================================================
// BRICK 109 — SAVE PLAYER DATA
// =========================================================

function savePlayerData() {


  // =========================================
  // SYNC CHARACTER PROGRESSION
  // =========================================


  syncRuntimeProgressionToPlayerData();



  // =========================================
  // SYNC ACTIVITY HISTORY
  // =========================================


  if (
    typeof activityHistory !==
      "undefined" &&
    Array.isArray(
      activityHistory
    )
  ) {


    playerData.activityHistory =
      activityHistory;


  }



  // =========================================
  // SAVE PLAYER DATA
  // =========================================


  localStorage.setItem(
    PLAYER_SAVE_KEY,
    JSON.stringify(
      playerData
    )
  );



  console.log(
    "Player save updated:",
    playerData
  );


}


// =========================================================
// CREATE INVENTORY ITEM ID
// =========================================================

function createInventoryItemId(
  itemName
) {


  return String(
    itemName
  )
    .toLowerCase()
    .trim()

    // =========================================
    // REMOVE APOSTROPHES
    // Captain's becomes Captains
    // =========================================

    .replace(
      /['’]/g,
      ""
    )

    // =========================================
    // CONVERT SPACES / SYMBOLS
    // TO UNDERSCORES
    // =========================================

    .replace(
      /[^a-z0-9]+/g,
      "_"
    )

    // =========================================
    // REMOVE OUTER UNDERSCORES
    // =========================================

    .replace(
      /^_+|_+$/g,
      ""
    );

}


// =========================================================
// ADD ITEM TO INVENTORY
// =========================================================

function addItemToInventory(
  item
) {


  if (
    !item ||
    !item.name
  ) {

    console.log(
      "Invalid inventory item:",
      item
    );


    return;

  }



  // =========================================
  // FIND ITEM DATABASE ENTRY
  // =========================================

  const generatedId =
    item.id ||
    createInventoryItemId(
      item.name
    );


  const definition =
    getItemDefinition(
      generatedId
    );



  // =========================================
  // BUILD INVENTORY ITEM DATA
  // =========================================

  const inventoryItemData = {

    id:
      generatedId,

    name:
      definition
        ? definition.name
        : item.name,

    type:
      definition
        ? definition.type
        : "misc",

    rarity:
      definition
        ? definition.rarity
        : (
            item.rarity ||
            "Common"
          ),

    stackable:
      definition
        ? definition.stackable
        : true

  };



  // =========================================
  // STACKABLE ITEMS
  // =========================================

  if (
    inventoryItemData.stackable
  ) {


    const existingItem =
      playerData.inventory.find(
        inventoryItem =>
          inventoryItem.id ===
          inventoryItemData.id
      );


    if (existingItem) {


      existingItem.quantity =
        (
          existingItem.quantity ||
          0
        ) +
        1;


      console.log(
        `${inventoryItemData.name} increased to ×${existingItem.quantity}`
      );


      return;

    }

  }



  // =========================================
  // CREATE NEW INVENTORY ENTRY
  // =========================================

  const newInventoryItem = {

    id:
      inventoryItemData.id,

    name:
      inventoryItemData.name,

    type:
      inventoryItemData.type,

    rarity:
      inventoryItemData.rarity,

    quantity:
      1

  };



  // =========================================
  // NON-STACKABLE ITEM INSTANCE
  // =========================================

  if (
    !inventoryItemData.stackable
  ) {


    newInventoryItem.instanceId =
      `${inventoryItemData.id}_${Date.now()}_${Math.floor(
        Math.random() *
        100000
      )}`;

  }



  // =========================================
  // EQUIPMENT DATA
  // =========================================

  if (
    definition &&
    definition.type ===
      "weapon"
  ) {


    newInventoryItem.weaponClass =
      definition.weaponClass;


    newInventoryItem.equipmentSlot =
      definition.equipmentSlot;


    newInventoryItem.equippedBy =
      null;

  }



  playerData.inventory.push(
    newInventoryItem
  );


  console.log(
    `New item obtained: ${newInventoryItem.name}`
  );

}


// =========================================================
// BRICK 340 — INVENTORY STACK QUANTITY AUTHORITY
// =========================================================
//
// Battle Items consume the real persistent Inventory stack.
// No Battle-only quantity copy exists.
//
// =========================================================

function getInventoryStackByItemId(
  itemId
) {


  if (
    !itemId ||
    !playerData ||
    !Array.isArray(
      playerData.inventory
    )
  ) {

    return null;
  }


  return (
    playerData.inventory.find(
      item =>
        item &&
        item.id ===
          itemId &&
        !item.instanceId
    ) ||
    null
  );
}


function getInventoryStackQuantity(
  itemId
) {


  const stack =
    getInventoryStackByItemId(
      itemId
    );


  return stack
    ? Math.max(
        0,
        Math.floor(
          Number(
            stack.quantity
          ) || 0
        )
      )
    : 0;
}


function consumeInventoryStackQuantity(
  itemId,
  amount = 1
) {


  const definition =
    getItemDefinition(
      itemId
    );


  const stack =
    getInventoryStackByItemId(
      itemId
    );


  const quantity =
    Math.max(
      1,
      Math.floor(
        Number(
          amount
        ) || 1
      )
    );


  if (
    !definition ||
    definition.stackable !==
      true ||
    !stack
  ) {

    return {

      success:
        false,

      reason:
        "inventory_stack_unavailable"

    };
  }


  const before =
    getInventoryStackQuantity(
      itemId
    );


  if (
    before <
      quantity
  ) {

    return {

      success:
        false,

      reason:
        "insufficient_inventory_quantity",

      quantityBefore:
        before

    };
  }


  stack.quantity =
    before -
    quantity;


  return {

    success:
      true,

    itemId:
      itemId,

    quantityBefore:
      before,

    quantityAfter:
      stack.quantity

  };
}


function restoreInventoryStackQuantity(
  itemId,
  amount = 1
) {


  const stack =
    getInventoryStackByItemId(
      itemId
    );


  if (
    !stack
  ) {

    return false;
  }


  const quantity =
    Math.max(
      1,
      Math.floor(
        Number(
          amount
        ) || 1
      )
    );


  stack.quantity =
    getInventoryStackQuantity(
      itemId
    ) +
    quantity;


  return true;
}


// =========================================================
// BRICK 157 — BATTLE CHRONICLE RESULT
// BRICK 611 — STABLE ENCOUNTER-ENEMY CHRONICLE AUTHORITY
// BRICK 642 — ACTIVE KONOHA OCCURRENCE SCOPE
// =========================================================
//
// Converts completed Battle state into
// Chronicle-compatible history data.
//
// =========================================================


function createBattleChronicleResult() {


  const encounterEnemy=
    getBattleEncounterEnemy();


  if (
    !currentBattle ||
    !encounterEnemy ||
    !currentBattle.rewards ||
    currentBattle.battleOver !==
      true
  ) {


    return null;


  }


  const rewards =
    currentBattle.rewards;


  const itemRewards = [

    ...(
      Array.isArray(
        rewards.items
      )
        ? rewards.items
        : []
    ),

    ...(
      Array.isArray(
        rewards.rareDrops
      )
        ? rewards.rareDrops
        : []
    )

  ].map(
    item => ({


      id:
        item.id ||
        createInventoryItemId(
          item.name
        ),


      name:
        item.name,


      rarity:
        item.rarity ||
        "Common",


      amount:
        1


    })
  );


  return {


    historyScope:
      createHistoryScopeAddress("active_konoha_chronicle_occurrence",{continuityId:ACTIVE_KONOHA_CONTINUITY_ID,occurrenceType:"battle"}),


    type:
      "battle",


    battleId:
      currentBattle.battleId,


    activity:
      "battle",


    encounterId:
      currentBattle.encounterId,


    enemyId:
      encounterEnemy.id,


    enemyName:
      encounterEnemy.name,


    character:
      currentBattle.characterId,


    success:
      true,


    finishingShinobi:
      rewards.finishingShinobi ||
      null,


    mvp:
      rewards.mvp
        ? {
            ...rewards.mvp
          }
        : null,


    rewards: {


      exp:
        Number(
          rewards.exp
        ) || 0,


      ryo:
        Number(
          rewards.ryo
        ) || 0,


      items:
        itemRewards,


      progression:
        []


    },


    timestamp:
      currentBattle.completedAt ||
      Date.now()


  };


}

// =========================================================
// BRICK 158 — BATTLE CHRONICLE RECORD
// =========================================================
//
// Persists one completed Battle exactly once.
//
// =========================================================


function recordBattleChronicle() {


  const result =
    createBattleChronicleResult();


  if (
    !result ||
    !result.battleId
  ) {


    console.log(
      "Battle Chronicle result unavailable."
    );


    return false;


  }


  const duplicate =
    getActivityHistory()
      .some(
        entry =>
          entry &&
          entry.type ===
            "battle" &&
          entry.battleId ===
            result.battleId
      );


  if (
    duplicate ||
    currentBattle.completionRecorded ===
      true
  ) {


    console.log(
      "Battle Chronicle already recorded:",
      result.battleId
    );


    currentBattle.completionRecorded =
      true;


    return true;


  }


  activityHistory.push(
    result
  );


  currentBattle.completionRecorded =
    true;


  syncActivityHistory();


  console.log(
    "Battle Chronicle recorded:",
    result
  );


  return true;


}

// =========================================================
// BRICK 159 — ENCOUNTER-AWARE BATTLE REWARD CLAIM
// =========================================================
//
// Canonical Battle victory payout.
//
// Handles:
//
// - Duplicate claim protection
// - Ryō
// - EXP
// - Common items
// - Rare items
// - Battle Chronicle
// - Persistence
//
// =========================================================


function claimCurrentBattleRewards() {


  const rewards =
    currentBattle.rewards;


  if (
    !rewards ||
    !rewards.generated
  ) {


    console.log(
      "No battle rewards available to claim."
    );


    return false;


  }


  if (
    rewards.claimed ===
      true
  ) {


    console.log(
      "Battle rewards have already been claimed."
    );


    return false;


  }


  // =========================================
  // RYO
  // =========================================


  playerData.ryo +=
    Number(
      rewards.ryo
    ) || 0;


  // =========================================
  // EXP
  // =========================================


  playerData.exp +=
    Number(
      rewards.exp
    ) || 0;


  // =========================================
  // COMMON ITEMS
  // =========================================


  if (
    Array.isArray(
      rewards.items
    )
  ) {


    rewards.items.forEach(
      item => {


        addItemToInventory(
          item
        );


      }
    );


  }


  // =========================================
  // RARE ITEMS
  // =========================================


  if (
    Array.isArray(
      rewards.rareDrops
    )
  ) {


    rewards.rareDrops.forEach(
      item => {


        addItemToInventory(
          item
        );


      }
    );


  }


  // =========================================
  // CLAIM STATE
  // =========================================


  rewards.claimed =
    true;


  currentBattle.claimedAt =
    Date.now();


  // =========================================
  // CHRONICLE
  // =========================================


  const chronicleRecorded =
    recordBattleChronicle();


  if (
    !chronicleRecorded
  ) {


    console.warn(
      "Battle rewards claimed but Chronicle recording failed."
    );


  }


  // =========================================
  // SAVE
  // =========================================


  savePlayerData();


  console.log(
    "================================="
  );


  console.log(
    "BATTLE REWARDS CLAIMED"
  );


  console.log(
    `Ryō: ${playerData.ryo}`
  );


  console.log(
    `EXP: ${playerData.exp}`
  );


  console.log(
    "Battle Chronicle:",
    chronicleRecorded
  );


  console.log(
    "================================="
  );


  return true;


}


// =========================================================
// PLAYER EQUIPMENT SYSTEM
// =========================================================

function getPlayerCharacter(
  characterId
) {


  return (
    playerTeam.find(
      character =>
        character.id ===
        characterId
    ) ||
    null
  );

}



// =========================================================
// FIND AVAILABLE INVENTORY EQUIPMENT
// =========================================================

function findAvailableEquipment(
  itemId
) {


  return (
    playerData.inventory.find(
      item =>
        item.id === itemId &&
        item.type === "weapon" &&
        !item.equippedBy
    ) ||
    null
  );

}



// =========================================================
// EQUIP ITEM TO CHARACTER
// =========================================================

function equipItemToCharacter(
  itemId,
  characterId
) {


  const character =
    getPlayerCharacter(
      characterId
    );


  if (!character) {


    console.log(
      "Character not found:",
      characterId
    );


    return false;

  }



  const item =
    findAvailableEquipment(
      itemId
    );


  if (!item) {


    console.log(
      "No unequipped item available:",
      itemId
    );


    return false;

  }



  const definition =
    getItemDefinition(
      item.id
    );


  if (
    !definition ||
    definition.type !==
      "weapon"
  ) {


    console.log(
      "Item cannot be equipped:",
      item.name
    );


    return false;

  }



  // =========================================
  // PREPARE CHARACTER EQUIPMENT ARRAY
  // =========================================

  if (
    !Array.isArray(
      character.equipment
    )
  ) {


    character.equipment =
      [];

  }



  // =========================================
  // CURRENTLY ONE WEAPON SLOT
  // =========================================

  const existingWeapon =
    character.equipment.find(
      equipment =>
        equipment.slot ===
        "weapon"
    );


  if (existingWeapon) {


    console.log(
      `${character.name} already has a weapon equipped.`
    );


    console.log(
      "Unequip the current weapon first."
    );


    return false;

  }



  // =========================================
  // EQUIP WEAPON
  // =========================================

  item.equippedBy =
    character.id;


  character.equipment.push({

    instanceId:
      item.instanceId,

    itemId:
      item.id,

    slot:
      "weapon"

  });



  savePlayerData();



  console.log(
    `${item.name} equipped by ${character.name}.`
  );


  return true;

}



// =========================================================
// UNEQUIP CHARACTER WEAPON
// =========================================================

function unequipCharacterWeapon(
  characterId
) {


  const character =
    getPlayerCharacter(
      characterId
    );


  if (!character) {


    console.log(
      "Character not found:",
      characterId
    );


    return false;

  }



  if (
    !Array.isArray(
      character.equipment
    ) ||
    character.equipment.length ===
      0
  ) {


    console.log(
      `${character.name} has no equipment.`
    );


    return false;

  }



  const equippedWeapon =
    character.equipment.find(
      equipment =>
        equipment.slot ===
        "weapon"
    );


  if (!equippedWeapon) {


    console.log(
      `${character.name} has no weapon equipped.`
    );


    return false;

  }



  const inventoryItem =
    playerData.inventory.find(
      item =>
        item.instanceId ===
        equippedWeapon.instanceId
    );


  if (inventoryItem) {


    inventoryItem.equippedBy =
      null;

  }



  character.equipment =
    character.equipment.filter(
      equipment =>
        equipment.instanceId !==
        equippedWeapon.instanceId
    );



  savePlayerData();



  console.log(
    `${character.name}'s weapon has been unequipped.`
  );


  return true;

}



// =========================================================
// RESTORE EQUIPMENT FROM PLAYER SAVE
// =========================================================

function syncCharacterEquipmentFromSave() {


  // =========================================
  // CLEAR RUNTIME EQUIPMENT
  // =========================================

  playerTeam.forEach(
    character => {

      character.equipment =
        [];

    }
  );


  if (
    !Array.isArray(
      playerData.inventory
    )
  ) {

    playerData.inventory =
      [];

  }


  const usedInstanceIds =
    new Set();


  const occupiedSlots =
    new Set();


  let repairedSave =
    false;


  // =========================================
  // VALIDATE + RESTORE SAVED EQUIPMENT
  // =========================================

  playerData.inventory.forEach(
    item => {


      if (
        !item ||
        item.type !==
          "weapon"
      ) {

        return;

      }


      if (!item.equippedBy) {

        return;

      }


      // =========================================
      // VALID CHARACTER
      // =========================================

      const character =
        getPlayerCharacter(
          item.equippedBy
        );


      if (!character) {


        console.warn(
          "Invalid equipped character removed:",
          item.equippedBy,
          item.name
        );


        item.equippedBy =
          null;


        repairedSave =
          true;


        return;

      }


      // =========================================
      // VALID ITEM DEFINITION
      // =========================================

      const definition =
        getItemDefinition(
          item.id
        );


      if (
        !definition ||
        definition.type !==
          "weapon"
      ) {


        console.warn(
          "Invalid equipped weapon definition:",
          item.id
        );


        item.equippedBy =
          null;


        repairedSave =
          true;


        return;

      }


      // =========================================
      // VALID INSTANCE ID
      // =========================================

      if (!item.instanceId) {


        console.warn(
          "Equipped weapon missing instanceId:",
          item.name
        );


        item.equippedBy =
          null;


        repairedSave =
          true;


        return;

      }


      // =========================================
      // DUPLICATE INSTANCE PROTECTION
      // =========================================

      if (
        usedInstanceIds.has(
          item.instanceId
        )
      ) {


        console.warn(
          "Duplicate equipped item instance removed:",
          item.instanceId
        );


        item.equippedBy =
          null;


        repairedSave =
          true;


        return;

      }


      const slot =
        definition.equipmentSlot ||
        item.equipmentSlot ||
        "weapon";


      const slotKey =
        `${character.id}:${slot}`;


      // =========================================
      // ONE ITEM PER SLOT
      // =========================================

      if (
        occupiedSlots.has(
          slotKey
        )
      ) {


        console.warn(
          `${character.name} had multiple items in ${slot}. Extra item unequipped:`,
          item.name
        );


        item.equippedBy =
          null;


        repairedSave =
          true;


        return;

      }


      // =========================================
      // NORMALIZE INVENTORY EQUIPMENT DATA
      // =========================================

      item.weaponClass =
        definition.weaponClass;


      item.equipmentSlot =
        slot;


      // =========================================
      // RESTORE RUNTIME EQUIPMENT
      // =========================================

      character.equipment.push({

        instanceId:
          item.instanceId,

        itemId:
          item.id,

        slot:
          slot

      });


      usedInstanceIds.add(
        item.instanceId
      );


      occupiedSlots.add(
        slotKey
      );

    }
  );


  // =========================================
  // RE-SAVE ONLY IF REPAIRS WERE REQUIRED
  // =========================================

  if (repairedSave) {


    console.warn(
      "Equipment save contained invalid data and was repaired."
    );


    savePlayerData();

  }


  console.log(
    "Character equipment restored."
  );

}


// =========================================================
// DEVELOPMENT EQUIPMENT VIEW
// =========================================================
//
// Equipment presentation uses Effective state.
//
// Current PL remains persistent progression.
// Effective PL reflects equipment and other contextual
// stat effects.
//
// =========================================================

function showEquipmentData() {


  const equipmentView =
    playerTeam.map(
      character => {


        const weapon =
          character.equipment.find(
            equipment =>
              equipment.slot ===
              "weapon"
          );


        const inventoryItem =
          weapon
            ? playerData.inventory.find(
                item =>
                  item.instanceId ===
                  weapon.instanceId
              )
            : null;


        const definition =
          inventoryItem
            ? getItemDefinition(
                inventoryItem.id
              )
            : null;


        const rawBonuses =
          getRawEquipmentStatBonuses(
            character
          );


        const naturalProficiency =
          getNaturalWeaponProficiency(
            character
          );


        const activeProficiency =
          getWeaponProficiency(
            character
          );


        const signatureMultiplier =
          getSignatureWeaponAffinityMultiplier(
            character,
            definition
          );


        const finalBonuses =
          getEquipmentStatBonuses(
            character
          );


        const effectiveStats =
          getDevelopedEffectiveCharacterStats(
            character
          );


        return {

          character:
            character.name,

          weapon:
            inventoryItem
              ? inventoryItem.name
              : "—",

          weaponClass:
            definition &&
            definition.weaponClass
              ? definition.weaponClass
              : "—",

          naturalBuki:
            character.stats.buki,

          rawBukiBonus:
            rawBonuses.buki,

          naturalTier:
            naturalProficiency.name,

          activeTier:
            activeProficiency.name,

          activeScore:
            activeProficiency.proficiencyBuki,

          proficiencyMult:
            `${activeProficiency.multiplier.toFixed(
              2
            )}x`,

          signatureMult:
            `${signatureMultiplier.toFixed(
              2
            )}x`,

          finalBukiBonus:
            finalBonuses.buki,

          effectiveBuki:
            effectiveStats.buki,

          currentPL:
            calculateCurrentPL(
              character
            ),

          effectivePL:
            calculateEffectivePL(
              character
            )

        };

      }
    );


  console.table(
    equipmentView
  );

}


// =========================================================
// EQUIPMENT PHASE DIAGNOSTICS
// =========================================================

function runEquipmentPhaseDiagnostics() {


  console.log(
    "========================================"
  );


  console.log(
    "SHINOBI CHRONICLES — EQUIPMENT DIAGNOSTICS"
  );


  console.log(
    "========================================"
  );


  const results =
    [];


  // =========================================
  // PLAYER SAVE STRUCTURE
  // =========================================

  results.push({

    test:
      "Inventory exists",

    pass:
      Array.isArray(
        playerData.inventory
      )

  });


  results.push({

    test:
      "Character progression exists",

    pass:
      !!(
        playerData.characters &&
        typeof playerData.characters ===
          "object"
      )

  });


  // =========================================
  // INVENTORY INTEGRITY
  // =========================================

  const instanceIds =
    new Set();


  let duplicateInstanceIds =
    false;


  let invalidEquippedCharacter =
    false;


  let invalidEquippedDefinition =
    false;


  playerData.inventory.forEach(
    item => {


      if (
        item.instanceId
      ) {


        if (
          instanceIds.has(
            item.instanceId
          )
        ) {

          duplicateInstanceIds =
            true;

        }


        instanceIds.add(
          item.instanceId
        );

      }


      if (
        item.equippedBy &&
        !getPlayerCharacter(
          item.equippedBy
        )
      ) {

        invalidEquippedCharacter =
          true;

      }


      if (
        item.equippedBy &&
        !getItemDefinition(
          item.id
        )
      ) {

        invalidEquippedDefinition =
          true;

      }

    }
  );


  results.push({

    test:
      "No duplicate item instances",

    pass:
      !duplicateInstanceIds

  });


  results.push({

    test:
      "No invalid equipped character IDs",

    pass:
      !invalidEquippedCharacter

  });


  results.push({

    test:
      "No missing equipped item definitions",

    pass:
      !invalidEquippedDefinition

  });


  // =========================================
  // CHARACTER EQUIPMENT INTEGRITY
  // =========================================

  let duplicateSlots =
    false;


  let invalidRuntimeEquipment =
    false;


  playerTeam.forEach(
    character => {


      const slots =
        new Set();


      character.equipment.forEach(
        equipment => {


          if (
            slots.has(
              equipment.slot
            )
          ) {

            duplicateSlots =
              true;

          }


          slots.add(
            equipment.slot
          );


          const inventoryItem =
            playerData.inventory.find(
              item =>
                item.instanceId ===
                equipment.instanceId
            );


          if (
            !inventoryItem ||
            inventoryItem.equippedBy !==
              character.id
          ) {

            invalidRuntimeEquipment =
              true;

          }

        }
      );

    }
  );


  results.push({

    test:
      "No duplicate character equipment slots",

    pass:
      !duplicateSlots

  });


  results.push({

    test:
      "Runtime equipment matches inventory",

    pass:
      !invalidRuntimeEquipment

  });


  // =========================================
  // CALCULATION HEALTH
  // =========================================

  let validEffectiveStats =
    true;


  let validPowerLevels =
    true;


  let validProficiencies =
    true;


  playerTeam.forEach(
    character => {


      const effectiveStats =
        getEffectiveCharacterStats(
          character
        );


      Object.values(
        effectiveStats
      ).forEach(
        value => {


          if (
            !Number.isFinite(
              Number(value)
            )
          ) {

            validEffectiveStats =
              false;

          }

        }
      );


      const pl =
        calculateCurrentPL(
          character
        );


      if (
        !Number.isFinite(
          pl
        )
      ) {

        validPowerLevels =
          false;

      }


      const proficiency =
        getWeaponProficiency(
          character
        );


      if (
        !Number.isFinite(
          proficiency.multiplier
        ) ||
        !Number.isFinite(
          proficiency.proficiencyBuki
        )
      ) {

        validProficiencies =
          false;

      }

    }
  );


  results.push({

    test:
      "Effective stats are valid",

    pass:
      validEffectiveStats

  });


  results.push({

    test:
      "Power levels are valid",

    pass:
      validPowerLevels

  });


  results.push({

    test:
      "Weapon proficiency is valid",

    pass:
      validProficiencies

  });


  // =========================================
  // SPECIALIZATION SAVE HEALTH
  // =========================================

  let specializationDataValid =
    true;


  playerTeam.forEach(
    character => {


      const specializations =
        character.weaponSpecializations ||
        {};


      Object.values(
        specializations
      ).forEach(
        specialization => {


          const normalized =
            normalizeWeaponSpecializationRecord(
              specialization
            );


          if (
            !Number.isFinite(
              normalized.level
            ) ||
            !Number.isFinite(
              normalized.exp
            )
          ) {

            specializationDataValid =
              false;

          }

        }
      );

    }
  );


  results.push({

    test:
      "Weapon specialization data valid",

    pass:
      specializationDataValid

  });


  // =========================================
  // DISPLAY RESULTS
  // =========================================

  console.table(
    results
  );


  const failedTests =
    results.filter(
      result =>
        !result.pass
    );


  if (
    failedTests.length ===
      0
  ) {


    console.log(
      "✅ EQUIPMENT PHASE PASSED ALL DIAGNOSTICS"
    );

  }
  else {


    console.warn(
      `❌ EQUIPMENT PHASE HAS ${failedTests.length} FAILED TEST(S)`
    );


    console.table(
      failedTests
    );

  }


  console.log(
    "========================================"
  );


  showEquipmentData();


  return (
    failedTests.length ===
    0
  );

}


// =========================================================
// DISCIPLINE EXP REQUIREMENT
// =========================================================

function getDisciplineExpRequired(
  level
) {


  const safeLevel =
    Math.max(
      1,
      Math.floor(
        Number(level) || 1
      )
    );


  return (
    50 +
    (
      safeLevel - 1
    ) * 25
  );

}


// =========================================================
// GET CHARACTER DISCIPLINE PROGRESSION
// =========================================================

function getCharacterDisciplineProgression(
  characterId,
  disciplineId
) {


  const character =
    getPlayerCharacter(
      characterId
    );


  if (!character) {


    console.log(
      "Character not found:",
      characterId
    );


    return null;

  }


  const discipline =
    getShinobiDiscipline(
      disciplineId
    );


  if (!discipline) {


    console.log(
      "Discipline not found:",
      disciplineId
    );


    return null;

  }


  character.disciplineProgression =
    normalizeDisciplineProgression(
      character
        .disciplineProgression
    );


  return (
    character
      .disciplineProgression[
        disciplineId
      ]
  );

}


// =========================================================
// GET DISCIPLINE STAT GAIN PER LEVEL
// =========================================================

function getDisciplineStatGainPerLevel(
  disciplineId
) {


  const discipline =
    getShinobiDiscipline(
      disciplineId
    );


  if (!discipline) {

    return 0;

  }


  // =========================================
  // CURRENT BALANCE RULE
  // =========================================
  //
  // Every discipline training level gained
  // permanently increases its natural stat
  // by +1.
  //
  // This helper exists so balancing can be
  // changed later in one place.
  //
  // =========================================

  return 1;

}


// =========================================================
// APPLY PENDING DISCIPLINE STAT GROWTH
// =========================================================

function applyPendingDisciplineStatGrowth(
  characterId,
  disciplineId
) {


  const character =
    getPlayerCharacter(
      characterId
    );


  if (!character) {


    console.log(
      "Character not found:",
      characterId
    );


    return null;

  }


  const discipline =
    getShinobiDiscipline(
      disciplineId
    );


  if (!discipline) {


    console.log(
      "Discipline not found:",
      disciplineId
    );


    return null;

  }


  const progression =
    getCharacterDisciplineProgression(
      characterId,
      disciplineId
    );


  if (!progression) {

    return null;

  }


  if (
    !Number.isFinite(
      Number(
        progression.statLevelApplied
      )
    )
  ) {

    progression.statLevelApplied =
      1;

  }


  let statPointsGained =
    0;


  const statGainPerLevel =
    getDisciplineStatGainPerLevel(
      disciplineId
    );


  while (
    progression.statLevelApplied <
      progression.level
  ) {


    progression.statLevelApplied +=
      1;


    character.stats[
      disciplineId
    ] =
      (
        Number(
          character.stats[
            disciplineId
          ]
        ) || 0
      ) +
      statGainPerLevel;


    statPointsGained +=
      statGainPerLevel;

  }


  if (
    statPointsGained >
      0
  ) {


    console.log(
      `${character.name} gained +${statPointsGained} permanent ${discipline.name}.`
    );

  }


  return {

    statPointsGained:
      statPointsGained,

    stat:
      character.stats[
        disciplineId
      ],

    statLevelApplied:
      progression.statLevelApplied

  };

}


// =========================================================
// PROCESS DISCIPLINE LEVEL UPS
// =========================================================

function processDisciplineLevelUps(
  characterId,
  disciplineId
) {


  const character =
    getPlayerCharacter(
      characterId
    );


  if (!character) {


    console.log(
      "Character not found:",
      characterId
    );


    return null;

  }


  const discipline =
    getShinobiDiscipline(
      disciplineId
    );


  if (!discipline) {


    console.log(
      "Discipline not found:",
      disciplineId
    );


    return null;

  }


  const progression =
    getCharacterDisciplineProgression(
      characterId,
      disciplineId
    );


  if (!progression) {

    return null;

  }


  let levelsGained =
    0;


  let expRequired =
    getDisciplineExpRequired(
      progression.level
    );


  while (
    progression.exp >=
      expRequired
  ) {


    progression.exp -=
      expRequired;


    progression.level +=
      1;


    levelsGained +=
      1;


    console.log(
      `${character.name}'s ${discipline.name} Training reached Level ${progression.level}!`
    );


    expRequired =
      getDisciplineExpRequired(
        progression.level
      );

  }


  const statGrowth =
    applyPendingDisciplineStatGrowth(
      characterId,
      disciplineId
    );


  return {

    levelsGained:
      levelsGained,

    level:
      progression.level,

    exp:
      progression.exp,

    expToNext:
      getDisciplineExpRequired(
        progression.level
      ),

    statPointsGained:
      statGrowth
        ? statGrowth.statPointsGained
        : 0,

    stat:
      character.stats[
        disciplineId
      ]

  };

}


// =========================================================
// VALIDATE DISCIPLINE TRAINING SOURCE
// =========================================================

function isValidDisciplineTrainingSource(
  disciplineId,
  source
) {


  const discipline =
    getShinobiDiscipline(
      disciplineId
    );


  if (!discipline) {

    return false;

  }


  return (
    discipline.trainingSource ===
    source
  );

}

// =========================================================
// BRICK 128 — PLAYER LOOP ACTIVITY TYPES
// =========================================================
//
// Aligns Player Loop requests with
// the canonical Activity Engine.
//
// Handles:
// - Practical training
// - Exams
// - Missions
// - Battles
//
// =========================================================


const PLAYER_ACTIVITY_TYPES = {


  TRAINING:
    "training",


  PRACTICAL:
    "practical",


  BATTLE:
    "battle",


  MISSION:
    "mission",


  EXAM:
    "exam"


};


// =========================================================
// BRICK 129 — EXECUTE PLAYER ACTIVITY
// =========================================================
//
// Entry point for Player Loop activity requests.
//
// Delegates execution to the canonical
// Activity Engine.
//
// =========================================================


function executePlayerActivity(
  activityRequest
) {


  if (
    !activityRequest ||
    typeof activityRequest !==
      "object"
  ) {


    console.log(
      "Invalid player activity request."
    );


    return false;


  }



  if (
    !Object.values(
      PLAYER_ACTIVITY_TYPES
    ).includes(
      activityRequest.type
    )
  ) {


    console.log(
      "Unknown player activity:",
      activityRequest.type
    );


    return false;


  }



  console.log(
    "PLAYER ACTIVITY START:",
    activityRequest
  );



  const result =
    processPlayerActivity(
      activityRequest
    );



  if (
    !result
  ) {


    console.log(
      "Player activity failed."
    );


    return false;


  }



  console.log(
    "PLAYER ACTIVITY COMPLETE:",
    result
  );



  return result;


}

// =========================================================
// BRICK 130 — PROCESS PLAYER ACTIVITY
// BRICK 311 — BATTLE ACTIVITY PHASE BOUNDARY
// BRICK 555 — MISSION ACTIVITY PHASE BOUNDARY
// =========================================================
//
// Routes Player Loop requests into
// the registered Activity Engine.
//
// Location/opportunity availability and actual completion are
// explicitly different lifecycle phases for Battle and Mission.
//
// Merely entering a Battle or Mission location must NEVER
// execute completion rewards / progression / history.
//
// =========================================================

function processPlayerActivity(
  activityRequest
) {


  switch (
    activityRequest.type
  ) {


    // =========================================
    // TRAINING UI AVAILABILITY REQUEST
    // =========================================

    case PLAYER_ACTIVITY_TYPES.TRAINING:


      if (
        activityRequest.stage ===
          "available"
      ) {


        return {

          success:
            true,

          type:
            "training_available",

          location:
            activityRequest.location ||
            null,

          activityId:
            activityRequest.activityId ||
            null,

          message:
            "Training opportunity available."

        };
      }


      console.log(
        "Direct legacy training execution is disabled."
      );


      return false;


    // =========================================
    // PRACTICAL
    // =========================================

    case PLAYER_ACTIVITY_TYPES.PRACTICAL:


      return startRegisteredActivity(
        "practical",
        activityRequest.characterId
      );


    // =========================================
    // BATTLE
    // =========================================

    case PLAYER_ACTIVITY_TYPES.BATTLE:


      // =======================================
      // LOCATION / OPPORTUNITY PHASE
      // =======================================

      if (
        activityRequest.stage ===
          "available"
      ) {


        return {

          success:
            true,

          type:
            "battle_available",

          location:
            activityRequest.location ||
            null,

          encounterId:
            activityRequest.encounterId ||
            null,

          message:
            "Battle opportunity available."

        };
      }


      // =======================================
      // EXPLICIT COMPLETION PHASE ONLY
      // =======================================

      if (
        activityRequest.stage !==
          "completion"
      ) {


        console.log(
          "Battle Activity execution requires an explicit lifecycle stage."
        );


        return false;
      }


      if (
        !activityRequest.characterId
      ) {


        console.log(
          "Battle completion requires a character ID."
        );


        return false;
      }


      return startRegisteredActivity(
        "battle",
        activityRequest.characterId
      );


    // =========================================
    // MISSION
    // BRICK 555 — EXPLICIT MISSION LIFECYCLE
    // =========================================

    case PLAYER_ACTIVITY_TYPES.MISSION:


      // =======================================
      // LOCATION / OPPORTUNITY PHASE
      // =======================================

      if (
        activityRequest.stage ===
          "available"
      ) {


        return {

          success:
            true,

          type:
            "mission_available",

          location:
            activityRequest.location ||
            null,

          missionId:
            activityRequest.missionId ||
            null,

          message:
            "Mission opportunity available."

        };
      }


      // =======================================
      // EXPLICIT COMPLETION PHASE ONLY
      // =======================================

      if (
        activityRequest.stage !==
          "completion"
      ) {


        console.log(
          "Mission Activity execution requires an explicit lifecycle stage."
        );


        return false;
      }


      if (
        !activityRequest.characterId
      ) {


        console.log(
          "Mission completion requires a character ID."
        );


        return false;
      }


      return startRegisteredActivity(
        "mission",
        activityRequest.characterId
      );


    // =========================================
    // EXAM
    // =========================================

    case PLAYER_ACTIVITY_TYPES.EXAM:


      return startRegisteredActivity(
        "exam",
        activityRequest.characterId
      );


    default:


      console.log(
        "Unknown activity type:",
        activityRequest.type
      );


      return false;

  }

}

// =========================================================
// BRICK 313 — BATTLE ACTIVITY BOUNDARY DIAGNOSTIC
// =========================================================

function runBattleActivityBoundaryDiagnostics() {


  const availability =
    processPlayerActivity({

      type:
        PLAYER_ACTIVITY_TYPES.BATTLE,

      stage:
        "available",

      location:
        "diagnostic_location"

    });


  const invalidCompletion =
    processPlayerActivity({

      type:
        PLAYER_ACTIVITY_TYPES.BATTLE,

      stage:
        "completion"

    });


  const battleActivity =
    getActivityData(
      "battle"
    );


  const result = {


    availabilityAccepted:
      !!(
        availability &&
        availability.success ===
          true
      ),


    availabilityIsNotCompletion:
      !!(
        availability &&
        availability.type ===
          "battle_available"
      ),


    completionWithoutCharacterRejected:
      invalidCompletion ===
        false,


    registeredBattleStillExists:
      !!battleActivity,


    registeredBattleNotAutoExecuted:
      !!(
        availability &&
        availability.type !==
          "battle"
      )

  };


  result.pass =
    Object.values(
      result
    ).every(
      value =>
        value ===
        true
    );


  console.table(
    result
  );


  return result;
}



// =========================================================
// ADD DISCIPLINE EXP
// =========================================================

function addDisciplineExp(
  characterId,
  disciplineId,
  amount,
  source
) {


  const character =
    getPlayerCharacter(
      characterId
    );


  if (!character) {


    console.log(
      "Character not found:",
      characterId
    );


    return false;

  }


  const discipline =
    getShinobiDiscipline(
      disciplineId
    );


  if (!discipline) {


    console.log(
      "Discipline not found:",
      disciplineId
    );


    return false;

  }


  if (
    !isValidDisciplineTrainingSource(
      disciplineId,
      source
    )
  ) {


    console.log(
      `${discipline.name} EXP cannot be gained from ${source}.`
    );


    console.log(
      `Required source: ${discipline.trainingSource}`
    );


    return false;

  }


  const expAmount =
    Math.floor(
      Number(amount)
    );


  if (
    !Number.isFinite(
      expAmount
    ) ||
    expAmount <= 0
  ) {


    console.log(
      "Invalid discipline EXP amount:",
      amount
    );


    return false;

  }


  const progression =
    getCharacterDisciplineProgression(
      characterId,
      disciplineId
    );


  if (!progression) {

    return false;

  }


  // =========================================
  // AWARD EXP
  // =========================================

  progression.exp +=
    expAmount;


  console.log(
    `${character.name} gained +${expAmount} ${discipline.name} EXP from ${source}.`
  );


  // =========================================
  // PROCESS LEVEL UPS + STAT GROWTH
  // =========================================

  const levelResult =
    processDisciplineLevelUps(
      characterId,
      disciplineId
    );


  if (!levelResult) {

    return false;

  }


  // =========================================
  // SAVE RESULT
  // =========================================

  savePlayerData();


  console.log(
    `${discipline.name} Training Level: ${levelResult.level}`
  );


  console.log(
    `${discipline.name} EXP: ${levelResult.exp} / ${levelResult.expToNext}`
  );


  if (
    levelResult.levelsGained >
      0
  ) {


    console.log(
      `${discipline.name} Levels Gained: +${levelResult.levelsGained}`
    );

  }


  if (
    levelResult.statPointsGained >
      0
  ) {


    console.log(
      `${discipline.name} Permanent Stat Gain: +${levelResult.statPointsGained}`
    );

  }


  return true;

}


