// =========================================================
// BRICK 47 — TRANSITION RESULT VALIDATOR
// =========================================================

function validateRunTransitionResult(
  result
) {


  if (
    !result ||
    typeof result !==
      "object"
  ) {


    return {

      valid:
        false,

      reason:
        "Transition result is missing."

    };

  }


  if (
    result.success !==
      true
  ) {


    return {

      valid:
        false,

      reason:
        result.reason ||
        "Transition was not successful."

    };

  }


  if (
    result.transitionType !==
      "difficulty" &&
    result.transitionType !==
      "legacy"
  ) {


    return {

      valid:
        false,

      reason:
        "Transition type is invalid."

    };

  }


  if (
    !getShinobiDifficulty(
      result.targetDifficultyId
    )
  ) {


    return {

      valid:
        false,

      reason:
        "Transition target difficulty is invalid."

    };

  }


  if (
    !Number.isFinite(
      Number(
        result.legacyCycle
      )
    ) ||
    Number(
      result.legacyCycle
    ) < 0
  ) {


    return {

      valid:
        false,

      reason:
        "Transition Legacy Cycle is invalid."

    };

  }


  return {

    valid:
      true,

    reason:
      null

  };

}


// =========================================================
// BRICK 48 — TRANSITION RECORD BUILDER
// =========================================================
//
// Later this can feed:
// - Ninja ID history
// - Codex
// - Achievements
// - Legacy statistics
// - player profile records
//
// =========================================================

function buildRunTransitionRecord(
  result
) {


  const validation =
    validateRunTransitionResult(
      result
    );


  if (!validation.valid) {

    return null;

  }


  return {

    transitionType:
      result.transitionType,

    fromDifficultyId:
      result.fromDifficultyId ||
      null,

    fromDifficultyName:
      result.fromDifficultyName ||
      null,

    targetDifficultyId:
      result.targetDifficultyId,

    targetDifficultyName:
      result.targetDifficultyName,

    legacyCycle:
      Math.floor(
        Number(
          result.legacyCycle
        )
      ),

    inheritance:
      result.inheritance
        ? normalizeInheritanceSelection(
            result.inheritance
          )
        : null,

    preserveCollection:
      result.preserveCollection ===
      true

  };

}


