// =========================================================
// 2. ACTIVE REGION / LOCATION STATE
// =========================================================

var selectedRegionKey = null;
var selectedLocationNode = null;
var regionInfoOpen = false;
var playerPowerLevel = 2450;
var currentOverlayType = null;


// =========================================================
// 3. GLOBAL OVERLAY SYSTEM
// =========================================================

function openOverlay(type) {


  currentOverlayType =
    type;


  const overlay =
    document.getElementById(
      "screen-overlay"
    );


  const container =
    document.getElementById(
      "overlay-content-container"
    );


  if (
    !overlay ||
    !container
  ) {

    return;
  }


  // =========================================
  // BRICK 295 — BATTLE LIVE CANVAS MODE
  // =========================================
  //
  // Combat reuses the existing global overlay authority.
  // Only presentation changes while the live Battle screen
  // is open. Other overlay types remain unchanged.
  //
  // =========================================

  overlay.classList.toggle(
    "battle-live-open",
    type === "combat"
  );


  saveTestState();


  overlay.style.display =
    "flex";


  switch (type) {


    case "clan":

      renderClanOverlay(
        container
      );

      break;


    case "village":

      renderVillageOverlay(
        container
      );

      break;


    case "missions":

      renderGenericOverlay(
        container,
        "MISSION BOARD",
        "Choose story missions, side missions and regional assignments."
      );

      break;


    case "battle":

      renderBattleOverlay(
        container
      );

      break;


    case "combat":

      renderCombatOverlay(
        container
      );

      break;


    case "victory":

      renderVictoryOverlay(
        container
      );

      break;


    case "training":

      renderTrainingOverlay(
        container
      );

      break;


    case "events":

      renderGenericOverlay(
        container,
        "WORLD EVENTS",
        "Limited-time regional encounters and special rewards will appear here."
      );

      break;


    case "roster":

      // =========================================
      // BRICK 356 — LEGACY ROSTER ROUTE
      // =========================================
      //
      // YOUR CLAN is now the sole character-management surface.
      // Keep this route as a compatibility redirect only.
      //
      // =========================================

      currentOverlayType =
        "clan";

      renderClanOverlay(
        container
      );

      break;


    case "shop":

      renderGenericOverlay(
        container,
        "SPECIAL SHOP",
        "Purchase rare scrolls, equipment and special items."
      );

      break;


    case "exams":

      renderGenericOverlay(
        container,
        "SHINOBI EXAMS",
        "Take rank exams to progress through the shinobi hierarchy."
      );

      break;


    case "practical":

      renderGenericOverlay(
        container,
        "PRACTICAL TRAINING",
        "Complete tactical tests and practical shinobi exercises."
      );

      break;


    case "group":

      renderGenericOverlay(
        container,
        "GROUP",
        "Manage squads, teams and future clan-based activities."
      );

      break;


    case "defend":

      renderGenericOverlay(
        container,
        "VILLAGE DEFENCE",
        "Defend your territory from invading rogue shinobi and hostile factions."
      );

      break;


    case "kage":

      renderGenericOverlay(
        container,
        "KAGE",
        "Endgame leadership systems and Kage-level responsibilities."
      );

      break;


    default:

      renderGenericOverlay(
        container,
        "SYSTEM ACTIVE",
        "This Shinobi Chronicles module is currently under development."
      );

      break;
  }
}


// =========================================================
// 4. CLOSE / BACK OVERLAY
// =========================================================

function closeOverlay() {


  // =========================================
  // VICTORY SCREEN
  // Claim rewards before leaving
  // =========================================

  if (
    currentOverlayType ===
    "victory"
  ) {


    continueAfterVictory();


    return;

  }


  // =========================================
  // COMBAT
  // Return to encounter selection
  // =========================================

  if (
    currentOverlayType ===
    "combat"
  ) {


    currentBattle.active =
      false;


    openOverlay(
      "battle"
    );


    return;

  }


  // =========================================
  // BATTLE / LOCATION SCREEN
  // Return to current region map
  // =========================================

  if (
    currentOverlayType ===
      "battle" &&
    selectedRegionKey
  ) {


    openRegionHub(
      selectedRegionKey
    );


    return;

  }


  // =========================================
  // OTHER REGION SUB-SCREENS
  // =========================================

  if (
    selectedRegionKey &&
    currentOverlayType !==
      "region"
  ) {


    openRegionHub(
      selectedRegionKey
    );


    return;

  }


  // =========================================
  // REGION MAP
  // Return to world map
  // =========================================

  const overlay =
    document.getElementById(
      "screen-overlay"
    );


  if (!overlay) {

    return;

  }


  overlay.style.display =
    "none";


  overlay.classList.remove(
    "region-map-open"
  );


  currentOverlayType =
    null;


  selectedRegionKey =
    null;


  selectedLocationNode =
    null;


  saveTestState();

}


// =========================================================
// BRICK 155 — DEVELOPMENT BATTLE STATE SAVE
// BRICK 607 — ENEMY PARTICIPANT IDENTITY SAVE
// =========================================================
//
// Preserves Battle / Encounter context across refreshes.
//
// BRICK 299:
// - deployment
//
// BRICKS 302–304:
// - transient Battle state
// - Conditions
// - action sequence
// - structured Battle evidence
//
// =========================================================

function saveTestState() {


  const state = {

    overlayType:
      currentOverlayType,


    regionKey:
      selectedRegionKey,


    locationId:
      selectedLocationNode
        ? selectedLocationNode.id
        : null,


    enemyId:
      selectedEnemy
        ? selectedEnemy.id
        : null,


    enemyParticipantIds:
      getBattleEnemyParticipantIds(),


    battleId:
      currentBattle.battleId,


    encounterId:
      currentBattle.encounterId,


    characterId:
      currentBattle.characterId,


    enemyPower:
      currentBattle.enemyPower,


    enemyMaxPower:
      currentBattle.enemyMaxPower,


    activePlayerId:
      currentBattle.activePlayer
        ? currentBattle.activePlayer.id
        : null,


    deployment:
      getBattleDeploymentSaveState(),


    runtime:
      currentBattle.battleId
        ? getBattleRuntimeSaveState()
        : null,


    lastDamage:
      currentBattle.lastDamage,


    battleOver:
      currentBattle.battleOver,


    completedAt:
      currentBattle.completedAt,


    claimedAt:
      currentBattle.claimedAt,


    completionRecorded:
      currentBattle
        .completionRecorded ===
        true,


    battleLog:
      currentBattle.battleLog,


    rewards:
      currentBattle.rewards,


    contributions:
      currentBattle.contributions ||
      {}

  };


  sessionStorage.setItem(
    "shinobiTestState",
    JSON.stringify(
      state
    )
  );
}

// =========================================================
// 5. GENERIC OVERLAY
// =========================================================

function renderGenericOverlay(
  container,
  title,
  description
) {

  container.innerHTML = `

    <div style="
      display: flex;
      flex-direction: column;
      flex: 1;
      min-height: 0;
    ">

      <h2 style="
        color: #D6A93A;
        font-size: 16px;
        letter-spacing: 1px;
        margin-bottom: 8px;
      ">
        ${title}
      </h2>


      <p style="
        color: #94A3B8;
        font-size: 11px;
        line-height: 1.5;
      ">
        ${description}
      </p>

    </div>

  `;
}


// =========================================================
// BRICK 254 — KONOHA MAP SCREEN
// =========================================================
//
// Canonical Konoha village presentation.
//
// Uses:
// Assets/Backgrounds/konoha.png
//
// Existing openOverlay("village") remains the
// navigation authority.
//
// =========================================================


function renderVillageOverlay(
  container
) {


  if (!container) {

    return false;

  }


  container.innerHTML = `

    <div
      class="
        konoha-map-screen
      "
    >

      <img
        src="
          Assets/Backgrounds/konoha.png
        "
        alt="
          Hidden Leaf Village
        "
        class="
          konoha-map-image
        "
      >


      <!-- =====================================
           LAND OF FIRE RETURN
           ===================================== -->

      <button
        type="button"
        class="
          konoha-map-return
        "
        onclick="
          closeOverlay()
        "
        aria-label="
          Return to Land of Fire
        "
        title="
          Return to Land of Fire
        "
      >

        LAND OF FIRE

      </button>


      <!-- =====================================
           SHINOBI EXAMS HOTSPOT
           ===================================== -->

      <button
        type="button"
        class="
          konoha-map-hotspot
          konoha-map-hotspot-exams
        "
        onclick="
          openKonohaExamFromVillage()
        "
        aria-label="
          Enter Shinobi Exams
        "
        title="
          Shinobi Exams
        "
      >

        <span
          class="
            konoha-map-hotspot-label
          "
        >
          SHINOBI EXAMS
        </span>

      </button>


      <!-- =====================================
           PRACTICAL TRAINING DEV HOTSPOT
           ===================================== -->

      <button
        type="
          button
        "
        class="
          konoha-map-hotspot
          konoha-map-hotspot-practical
        "
        onclick="
          openKonohaPracticalFromVillage()
        "
        aria-label="
          Enter Practical Training
        "
        title="
          Practical Training
        "
      >

        <span
          class="
            konoha-map-hotspot-label
          "
        >
          PRACTICAL TRAINING
        </span>

      </button>


    </div>

  `;


  return true;

}


// =========================================================
// KONOHA → EXAMS
// =========================================================


function openKonohaExamFromVillage() {


  const overlay =
    document.getElementById(
      "screen-overlay"
    );


  if (overlay) {

    overlay.style.display =
      "none";

  }


  const result =
    showKonohaActivityUIScreen(
      "exams"
    );


  if (
    !result ||
    result.success !==
      true
  ) {


    if (overlay) {

      overlay.style.display =
        "flex";

    }


    return result;

  }


  return result;

}


// =========================================================
// KONOHA → PRACTICAL
// =========================================================


function openKonohaPracticalFromVillage() {


  const overlay =
    document.getElementById(
      "screen-overlay"
    );


  if (overlay) {

    overlay.style.display =
      "none";

  }


  const result =
    showKonohaActivityUIScreen(
      "practical"
    );


  if (
    !result ||
    result.success !==
      true
  ) {


    if (overlay) {

      overlay.style.display =
        "flex";

    }


    return result;

  }


  return result;

}


// =========================================================
// ACTIVITY UI → KONOHA
// =========================================================


function returnToKonohaFromActivityUI() {


  closeKonohaActivityUIScreen();


  openOverlay(
    "village"
  );


  return true;

}


// =========================================================
// BRICKS 354–356 — YOUR CLAN / CHARACTER MANAGEMENT
// =========================================================
//
// Functional Alpha foundation.
//
// Character identity / Stats / PL remain owned by playerTeam
// and the existing progression authorities.
//
// playerData.clan owns only persistent six-slot formation and
// favourites. Battle snapshots consume the formation but never
// mutate it.
//
// UI may replace this presentation later without moving these
// authorities into the UI layer.
//
// =========================================================

const CLAN_FILTER_IDS = [
  "all",
  "active",
  "reserve",
  "favourites"
];


const CLAN_UI_STATE = {

  filterId:
    "all",

  selectedCharacterId:
    null

};


function ensureClanManagementState() {


  const normalized =
    normalizeClanManagementState(
      playerData.clan
    );


  playerData.clan =
    normalized;


  return normalized;
}


function getClanTeamSlotNumber(
  characterId
) {


  const clan =
    ensureClanManagementState();


  const index =
    clan.teamSlots.indexOf(
      characterId
    );


  return index >= 0
    ? index + 1
    : null;
}


function getClanCharacterTeamStatus(
  characterId
) {


  const slotNumber =
    getClanTeamSlotNumber(
      characterId
    );


  if (
    slotNumber >= 1 &&
    slotNumber <= 3
  ) {


    return "ACTIVE";
  }


  if (
    slotNumber >= 4 &&
    slotNumber <= 6
  ) {


    return "RESERVE";
  }


  return "AVAILABLE";
}


function isClanFavourite(
  characterId
) {


  return ensureClanManagementState()
    .favoriteIds
    .includes(
      characterId
    );
}


function getClanFilteredCharacters(
  filterId = "all"
) {


  const roster =
    getClanManageableRosterCharacters();


  switch (filterId) {

    case "active":
      return roster.filter(
        character => {

          const slotNumber =
            getClanTeamSlotNumber(
              character.id
            );

          return (
            slotNumber >= 1 &&
            slotNumber <= 3
          );
        }
      );

    case "reserve":
      return roster.filter(
        character => {

          const slotNumber =
            getClanTeamSlotNumber(
              character.id
            );

          return (
            slotNumber >= 4 &&
            slotNumber <= 6
          );
        }
      );

    case "favourites":
      return roster.filter(
        character =>
          isClanFavourite(
            character.id
          )
      );

    default:
      return roster;
  }
}


function canEditClanFormation() {


  if (
    typeof currentBattle !==
      "undefined" &&
    currentBattle &&
    currentBattle.active ===
      true &&
    currentBattle.battleOver !==
      true
  ) {


    return {

      allowed:
        false,

      reason:
        "clan_team_locked_during_battle"

    };
  }


  return {

    allowed:
      true,

    reason:
      null

  };
}


function setClanTeamSlot(
  slotNumber,
  characterId
) {


  const editability =
    canEditClanFormation();


  if (
    !editability.allowed
  ) {


    return {

      success:
        false,

      reason:
        editability.reason

    };
  }


  const slotIndex =
    Number(slotNumber) - 1;


  if (
    !Number.isInteger(
      slotIndex
    ) ||
    slotIndex < 0 ||
    slotIndex >=
      CLAN_TEAM_SLOT_COUNT
  ) {


    return {

      success:
        false,

      reason:
        "invalid_clan_team_slot"

    };
  }


  const character =
    getClanManageableRosterCharacters()
      .find(
        member =>
          member.id ===
            characterId
      ) ||
    null;


  if (!character) {


    return {

      success:
        false,

      reason:
        "character_not_clan_manageable"

    };
  }


  const clan =
    ensureClanManagementState();


  const previousIndex =
    clan.teamSlots.indexOf(
      character.id
    );


  const displacedId =
    clan.teamSlots[
      slotIndex
    ] ||
    null;


  if (
    previousIndex ===
      slotIndex
  ) {


    return {

      success:
        true,

      changed:
        false,

      slotNumber:
        slotNumber,

      characterId:
        character.id

    };
  }


  clan.teamSlots[
    slotIndex
  ] =
    character.id;


  if (
    previousIndex >=
      0
  ) {


    clan.teamSlots[
      previousIndex
    ] =
      displacedId;
  }


  playerData.clan =
    normalizeClanManagementState(
      clan
    );


  savePlayerData();


  rerenderClanOverlay();


  return {

    success:
      true,

    changed:
      true,

    slotNumber:
      slotNumber,

    characterId:
      character.id,

    displacedCharacterId:
      displacedId

  };
}


// =========================================================
// BRICK 424 — NEXT-OPEN TEAM SLOT ASSIGNMENT
// BRICK 425 — TEAM REORDER AUTHORITY FOR FUTURE DRAG UI
// =========================================================

function assignClanCharacterToNextOpenSlot(characterId) {
  const editability=canEditClanFormation();
  if (!editability.allowed) return {success:false,reason:editability.reason};
  const character=getClanManageableRosterCharacters().find(member=>member.id===characterId)||null;
  if (!character) return {success:false,reason:"character_not_clan_manageable"};
  const clan=ensureClanManagementState();
  const existingIndex=clan.teamSlots.indexOf(characterId);
  if (existingIndex>=0) return {success:true,changed:false,slotNumber:existingIndex+1,characterId};
  const openIndex=clan.teamSlots.findIndex(id=>!id);
  if (openIndex<0) return {success:false,reason:"clan_team_full"};
  clan.teamSlots[openIndex]=characterId;
  playerData.clan=normalizeClanManagementState(clan);
  savePlayerData();
  rerenderClanOverlay();
  return {success:true,changed:true,slotNumber:openIndex+1,characterId};
}

function moveClanCharacterToSlot(characterId, slotNumber) {
  return setClanTeamSlot(slotNumber,characterId);
}

function removeClanCharacterFromTeam(
  characterId
) {


  const editability =
    canEditClanFormation();


  if (
    !editability.allowed
  ) {


    return {

      success:
        false,

      reason:
        editability.reason

    };
  }


  const clan =
    ensureClanManagementState();


  const slotIndex =
    clan.teamSlots.indexOf(
      characterId
    );


  if (
    slotIndex < 0
  ) {


    return {

      success:
        true,

      changed:
        false,

      reason:
        null

    };
  }


  const deployedCount =
    clan.teamSlots.filter(
      id =>
        !!id
    ).length;


  if (
    deployedCount <= 1
  ) {


    return {

      success:
        false,

      reason:
        "clan_team_requires_one_member"

    };
  }


  clan.teamSlots[
    slotIndex
  ] =
    null;


  playerData.clan =
    normalizeClanManagementState(
      clan
    );


  savePlayerData();


  rerenderClanOverlay();


  return {

    success:
      true,

    changed:
      true,

    characterId:
      characterId

  };
}


function toggleClanFavourite(
  characterId
) {


  const character =
    getClanManageableRosterCharacters()
      .find(
        member =>
          member.id ===
            characterId
      ) ||
    null;


  if (!character) {


    return {

      success:
        false,

      reason:
        "character_not_clan_manageable"

    };
  }


  const clan =
    ensureClanManagementState();


  if (
    clan.favoriteIds.includes(
      characterId
    )
  ) {


    clan.favoriteIds =
      clan.favoriteIds.filter(
        id =>
          id !==
            characterId
      );
  }
  else {


    clan.favoriteIds.push(
      characterId
    );
  }


  playerData.clan =
    normalizeClanManagementState(
      clan
    );


  savePlayerData();


  rerenderClanOverlay();


  return {

    success:
      true,

    characterId:
      characterId,

    favourite:
      isClanFavourite(
        characterId
      )

  };
}


function setClanFilter(
  filterId
) {


  CLAN_UI_STATE.filterId =
    CLAN_FILTER_IDS.includes(
      filterId
    )
      ? filterId
      : "all";


  rerenderClanOverlay();


  return CLAN_UI_STATE.filterId;
}


function selectClanCharacter(
  characterId
) {


  const character =
    getClanManageableRosterCharacters()
      .find(
        member =>
          member.id ===
            characterId
      ) ||
    null;


  if (!character) {


    return false;
  }


  CLAN_UI_STATE
    .selectedCharacterId =
      character.id;


  rerenderClanOverlay();


  return true;
}


function rerenderClanOverlay() {


  if (
    currentOverlayType !==
      "clan"
  ) {


    return false;
  }


  const container =
    document.getElementById(
      "overlay-content-container"
    );


  if (!container) {


    return false;
  }


  renderClanOverlay(
    container
  );


  return true;
}


function renderClanManagementControls(
  character
) {


  if (!character) {


    return `
      <div style="
        margin-bottom:12px;
        padding:10px 12px;
        border:1px solid #1e293b;
        border-radius:5px;
        color:#64748b;
        font-size:9px;
        background:#080d13;
      ">
        Select a shinobi to manage team placement or favourites.
      </div>
    `;
  }


  const slotNumber =
    getClanTeamSlotNumber(
      character.id
    );


  const favourite =
    isClanFavourite(
      character.id
    );


  const slotButtons =
    Array.from(
      {
        length:
          CLAN_TEAM_SLOT_COUNT
      },
      (_, index) => {


        const targetSlot =
          index + 1;


        const label =
          targetSlot <= 3
            ? `ACTIVE ${targetSlot}`
            : `RESERVE ${targetSlot}`;


        const selected =
          slotNumber ===
            targetSlot;


        return `
          <button
            type="button"
            onclick="setClanTeamSlot(${targetSlot}, '${character.id}')"
            style="
              padding:6px 8px;
              border:1px solid ${selected ? "#00d9e8" : "#263448"};
              border-radius:4px;
              background:${selected ? "rgba(0,217,232,0.12)" : "#0d141d"};
              color:${selected ? "#00d9e8" : "#94a3b8"};
              font-size:7px;
              font-weight:900;
              cursor:pointer;
            "
          >
            ${label}
          </button>
        `;
      }
    )
      .join("");


  return `
    <div style="
      margin-bottom:12px;
      padding:10px 12px;
      display:flex;
      align-items:center;
      gap:8px;
      flex-wrap:wrap;
      border:1px solid #263448;
      border-radius:5px;
      background:#080d13;
    ">
      <strong style="
        color:#ffffff;
        font-size:9px;
        margin-right:4px;
      ">
        ${character.name}
      </strong>

      ${slotButtons}

      <button
        type="button"
        onclick="removeClanCharacterFromTeam('${character.id}')"
        style="
          padding:6px 8px;
          border:1px solid #263448;
          border-radius:4px;
          background:#0d141d;
          color:#94a3b8;
          font-size:7px;
          font-weight:900;
          cursor:pointer;
        "
      >
        REMOVE FROM TEAM
      </button>

      <button
        type="button"
        onclick="toggleClanFavourite('${character.id}')"
        style="
          padding:6px 8px;
          border:1px solid ${favourite ? "#d6a93a" : "#263448"};
          border-radius:4px;
          background:${favourite ? "rgba(214,169,58,0.12)" : "#0d141d"};
          color:${favourite ? "#d6a93a" : "#94a3b8"};
          font-size:7px;
          font-weight:900;
          cursor:pointer;
        "
      >
        ${favourite ? "★ FAVOURITE" : "☆ FAVOURITE"}
      </button>
    </div>
  `;
}


function renderClanOverlay(
  container
) {


  ensureClanManagementState();


  const roster =
    getClanManageableRosterCharacters();


  if (
    !CLAN_UI_STATE.selectedCharacterId ||
    !roster.some(
      character =>
        character.id ===
          CLAN_UI_STATE
            .selectedCharacterId
    )
  ) {


    CLAN_UI_STATE
      .selectedCharacterId =
        roster.length > 0
          ? roster[0].id
          : null;
  }


  const selectedCharacter =
    CLAN_UI_STATE
      .selectedCharacterId
        ? getPlayerCharacter(
            CLAN_UI_STATE
              .selectedCharacterId
          )
        : null;


  const visibleCharacters =
    getClanFilteredCharacters(
      CLAN_UI_STATE.filterId
    );


  const filterButton =
    (
      filterId,
      label
    ) => `
      <button
        type="button"
        class="clan-filter-btn ${
          CLAN_UI_STATE.filterId ===
            filterId
              ? "active"
              : ""
        }"
        onclick="setClanFilter('${filterId}')"
      >
        ${label}
      </button>
    `;


  container.innerHTML = `

    <div class="clan-screen">

      <div class="clan-header">

        <div>

          <h2 class="clan-title">
            YOUR CLAN
          </h2>

          <p class="clan-description">
            View, organise and prepare the shinobi currently under your command.
          </p>

        </div>

        <div class="clan-count">
          <span>SHINOBI</span>
          <strong id="clan-roster-count">
            ${roster.length}
          </strong>
        </div>

      </div>


      <div class="clan-toolbar">

        ${filterButton(
          "all",
          "ALL"
        )}

        ${filterButton(
          "active",
          "ACTIVE TEAM"
        )}

        ${filterButton(
          "reserve",
          "RESERVE"
        )}

        ${filterButton(
          "favourites",
          "FAVOURITES"
        )}

      </div>


      ${renderClanManagementControls(
        selectedCharacter
      )}


      <div class="clan-roster-grid">

        ${
          visibleCharacters.length > 0
            ? visibleCharacters
                .map(
                  character =>
                    createClanCard(
                      character
                    )
                )
                .join("")
            : `
                <div style="
                  padding:18px;
                  color:#64748b;
                  font-size:9px;
                  border:1px solid #1e293b;
                  border-radius:6px;
                  background:#080d13;
                ">
                  No shinobi match this filter.
                </div>
              `
        }

      </div>

    </div>
  `;
}


function createClanCard(
  character
) {


  const status =
    getClanCharacterTeamStatus(
      character.id
    );


  const slotNumber =
    getClanTeamSlotNumber(
      character.id
    );


  const favourite =
    isClanFavourite(
      character.id
    );


  const currentPL =
    calculateCurrentPL(
      character
    );


  const selected =
    CLAN_UI_STATE
      .selectedCharacterId ===
        character.id;


  return `

    <button
      type="button"
      class="clan-card"
      onclick="selectClanCharacter('${character.id}')"
      style="${
        selected
          ? "border-color:#00d9e8;box-shadow:0 0 14px rgba(0,217,232,0.16);"
          : ""
      }"
    >

      <div class="clan-card-portrait">

        ${
          character.image
            ? `
                <img
                  src="${character.image}"
                  alt="${character.name}"
                  draggable="false"
                  style="
                    width:100%;
                    height:100%;
                    object-fit:cover;
                    object-position:center top;
                  "
                >
              `
            : `
                <span class="clan-card-placeholder">
                  忍
                </span>
              `
        }

      </div>


      <div class="clan-card-body">

        <div class="clan-card-top">

          <div>

            <div class="clan-card-name">
              ${character.name}
              ${favourite ? " ★" : ""}
            </div>

            <div class="clan-card-rank">
              ${character.rank || "UNCLASSIFIED"}
            </div>

          </div>


          <span class="
            clan-card-status
            ${status.toLowerCase()}
          ">
            ${status}
          </span>

        </div>


        <div class="clan-card-stats">

          <div>
            <span>CURRENT PL</span>
            <strong>
              ${currentPL}
            </strong>
          </div>

          <div>
            <span>TEAM SLOT</span>
            <strong>
              ${slotNumber || "—"}
            </strong>
          </div>

        </div>

      </div>

    </button>
  `;
}


function runClanManagementDiagnostics() {


  const originalClan =
    JSON.parse(
      JSON.stringify(
        ensureClanManagementState()
      )
    );


  const originalUIState = {
    ...CLAN_UI_STATE
  };


  const results = {};


  try {


    const roster =
      getClanManageableRosterCharacters();


    const clan =
      ensureClanManagementState();


    results.rosterUsesPlayerTeamAuthority =
      roster.every(
        character =>
          playerTeam.includes(
            character
          )
      );


    results.ownershipControlsManageableRoster =
      roster.every(
        character =>
          isRuntimeCharacterOwned(character)
      );

    results.academyOwnedVariantsVisible =
      ACADEMY_BATTLE_PILOT_PARTICIPANT_IDS.every(
        characterId =>
          roster.some(character => character.id === characterId)
      );


    results.sixPersistentSlots =
      Array.isArray(
        clan.teamSlots
      ) &&
      clan.teamSlots.length ===
        CLAN_TEAM_SLOT_COUNT;


    const configuredIds =
      clan.teamSlots.filter(
        characterId =>
          !!characterId
      );


    results.uniqueTeamParticipants =
      new Set(
        configuredIds
      ).size ===
      configuredIds.length;


    results.activeReserveSemantics =
      clan.teamSlots.every(
        (
          characterId,
          index
        ) =>
          !characterId ||
          getClanCharacterTeamStatus(
            characterId
          ) ===
            (
              index < 3
                ? "ACTIVE"
                : "RESERVE"
            )
      );


    results.battleConsumesClanFormation =
      JSON.stringify(
        getPersistentClanBattleParticipantIds()
      ) ===
      JSON.stringify(
        configuredIds.length > 0
          ? configuredIds
          : getClanManageableRosterCharacters()
              .slice(
                0,
                CLAN_TEAM_SLOT_COUNT
              )
              .map(
                character =>
                  character.id
              )
      );


    const firstCharacter =
      roster[0] ||
      null;


    if (firstCharacter) {


      const beforeFavourite =
        isClanFavourite(
          firstCharacter.id
        );


      toggleClanFavourite(
        firstCharacter.id
      );


      results.favouriteToggleWorks =
        isClanFavourite(
          firstCharacter.id
        ) !==
        beforeFavourite;
    }
    else {


      results.favouriteToggleWorks =
        true;
    }
  }
  finally {


    playerData.clan =
      originalClan;


    CLAN_UI_STATE.filterId =
      originalUIState.filterId;


    CLAN_UI_STATE
      .selectedCharacterId =
        originalUIState
          .selectedCharacterId;


    savePlayerData();
  }


  results.pass =
    Object.values(
      results
    ).every(
      value =>
        value ===
          true
    );


  console.table(
    results
  );


  return results;
}



