// =========================================================
// REGIONAL SYMBOL
// =========================================================

function getRegionSymbol(type) {

  switch (type) {

    case "battle":
      return "▣";

    case "training":
      return "EXP";

    case "mission":
      return "◆";

    case "activity":
      return "✦";

    case "secret":
      return "?";

    case "outpost":
      return "▥";

    case "village":
      return "●";

    default:
      return "•";
  }

}



// =========================================================
// HOTSPOT GENERATOR
// =========================================================

function renderRegionHotspot(
  regionKey,
  location
) {

  const hoverSide =
    getHotspotHoverSide(
      location
    );


  return `

    <button
      type="button"

      class="
        region-hotspot
        region-hotspot-image
        ${location.type}
        ${hoverSide}
      "

      style="
        left: ${location.x}%;
        top: ${location.y}%;
      "

      onclick="
        selectMapNode(
          '${regionKey}',
          '${location.id}'
        )
      "

      aria-label="
        ${location.name}
      "
    >


      <span class="
        hotspot-icon-shell
      ">

        <img
          src="${location.icon}"

          alt=""

          class="
            hotspot-icon-image
          "
        >

      </span>


      <span class="
        hotspot-nameplate
      ">

        ${location.shortName || location.name}

      </span>


      ${renderHotspotHoverCard(
        location
      )}


    </button>

  `;

}



// =========================================================
// AUTOMATIC HOVER-CARD DIRECTION
// =========================================================

function getHotspotHoverSide(
  location
) {

  if (location.y > 76) {

    return "hover-up";
  }


  if (location.x >= 66) {

    return "hover-left";
  }


  return "hover-right";

}



