// =========================================================

function showCurrentLocationData() {


  const location =
    getCurrentLocationData();


  if (!location) {

    console.log(
      "No active location."
    );

    return;

  }


  console.table({
    Name:
      location.name,

    Type:
      location.type,

    Actions:
      location.actions.join(", ")

  });


}

