// =========================================================
// BRICK 184 — CONTENT ACCESS KEY
// =========================================================


function createContentAccessKey(
  contentType,
  contentId
) {


  if (
    !contentType ||
    !contentId
  ) {


    return null;


  }


  return (
    `${contentType}:${contentId}`
  );


}



// =========================================================
// BRICK 185 — CONTENT ACCESS DEFINITION QUERY
// =========================================================


function getContentAccessDefinition(
  contentType,
  contentId
) {


  const key =
    createContentAccessKey(
      contentType,
      contentId
    );


  if (
    !key
  ) {


    return null;


  }


  return (
    CONTENT_ACCESS_DATABASE[
      key
    ] ||
    null
  );


}



// =========================================================
// BRICK 186 — CONTENT ACCESS EVALUATOR
// =========================================================
//
// Missing access definitions are treated as OPEN.
//
// This keeps legacy / unfinished content functional
// until it receives an explicit access definition.
//
// =========================================================


function evaluateContentAccess(
  contentType,
  contentId
) {


  const definition =
    getContentAccessDefinition(
      contentType,
      contentId
    );


  if (
    !definition
  ) {


    return {

      exists:
        false,

      accessible:
        true,

      contentType:
        contentType || null,

      contentId:
        contentId || null,

      requirements:
        [],

      evaluation:
        {

          valid:
            true,

          met:
            true,

          results:
            []

        }

    };


  }


  const evaluation =
    evaluateChronicleRequirements(
      Array.isArray(
        definition.requirements
      )
        ? definition.requirements
        : []
    );


  return {

    exists:
      true,

    accessible:
      (
        evaluation.valid ===
          true &&
        evaluation.met ===
          true
      ),

    contentType:
      definition.type,

    contentId:
      definition.id,

    requirements:
      definition.requirements,

    evaluation:
      evaluation

  };


}



// =========================================================
// BRICK 187 — CONTENT ACCESS BOOLEAN BRIDGE
// =========================================================


function canAccessContent(
  contentType,
  contentId
) {


  return evaluateContentAccess(
    contentType,
    contentId
  ).accessible ===
    true;


}



// =========================================================
// BRICK 188 — CONTENT ACCESS PROGRESS
// =========================================================
//
// UI-safe access information.
//
// Future use:
//
// - LOCKED
// - 1 / 5 Scout defeats
// - Complete Exam first
//
// =========================================================


function getContentAccessProgress(
  contentType,
  contentId
) {


  const access =
    evaluateContentAccess(
      contentType,
      contentId
    );


  return {

    accessible:
      access.accessible,

    contentType:
      access.contentType,

    contentId:
      access.contentId,

    requirements:
      access.requirements.map(
        requirement =>
          getChronicleRequirementProgress(
            requirement
          )
      )

  };


}



