// =========================================================
// BRICK 190 — LOCATION ACTION ACCESS CHECK
// =========================================================
//
// Location validity
// ↓
// Activity validity
// ↓
// Chronicle content access
//
// =========================================================


function canLaunchLocationAction(
  locationId,
  action
) {


  if (
    !validateLocationActivity(
      locationId,
      action
    )
  ) {


    return false;


  }


  const locationAccess =
    getLocationActionAccessStatus(
      locationId,
      action
    );


  if (
    !locationAccess.accessible
  ) {


    console.log(
      "Location action locked:",
      locationId,
      action,
      locationAccess
    );


    return false;


  }


  const activityId =
    getLocationActivity(
      locationId,
      action
    );


  if (
    !activityId
  ) {


    return false;


  }


  const activityAccess =
    getActivityAccessStatus(
      activityId
    );


  if (
    !activityAccess.accessible
  ) {


    console.log(
      "Activity locked:",
      activityId,
      activityAccess
    );


    return false;


  }


  return true;


}



// =========================================
// CURRENT PLAYER LOCATION STATE
// =========================================


let currentPlayerLocation =
  null;




function setPlayerLocation(
  locationId
) {


  if (
    !getLocationData(
      locationId
    )
  ) {


    return false;


  }



  currentPlayerLocation =
    locationId;



  discoverLocation(
    locationId
  );



  return true;


}




function getPlayerLocation() {


  return currentPlayerLocation;


}

// =========================================
// LOCATION TRAVEL VALIDATION
// =========================================


function canTravelToLocation(
  locationId
) {


  const location =
    getLocationData(
      locationId
    );


  if (!location) {

    return false;

  }


  return checkLocationRequirements(
    locationId
  );


}


// =========================================
// CURRENT LOCATION ACTION LIST
// =========================================


function getCurrentLocationActions() {


  const locationId =
    getPlayerLocation();



  if (!locationId) {

    return [];

  }



  return getLocationActions(
    locationId
  );


}

// =========================================================
// BRICK 124 — LOCATION ACTIVITY EXECUTION ROUTER
// =========================================================
//
// Routes the player's current location action
// into the Activity Engine.
//
// Preserves character identity through:
// Location
// ↓
// Activity
// ↓
// Progression
//
// =========================================================


function executeLocationAction(
  action,
  characterId
) {


  const locationId =
    getPlayerLocation();



  if (
    !locationId
  ) {


    console.log(
      "No active player location."
    );


    return false;


  }



  if (
    !characterId ||
    !getPlayerCharacter(
      characterId
    )
  ) {


    console.log(
      "Invalid location activity character:",
      characterId
    );


    return false;


  }



  if (
    !canLaunchLocationAction(
      locationId,
      action
    )
  ) {


    console.log(
      "Action unavailable:",
      action
    );


    return false;


  }



  return launchLocationAction(
    locationId,
    action,
    characterId
  );


}

// =========================================
// CURRENT LOCATION RETURN STATE
// =========================================


function leaveCurrentLocation() {


  currentPlayerLocation =
    null;


  return true;


}





function hasActiveLocation() {


  return (
    currentPlayerLocation !== null
  );


}

// =========================================
