// =========================================


let locationHistory = [];





function recordLocationVisit(
  locationId
) {


  if (
    !locationHistory.includes(
      locationId
    )
  ) {


    locationHistory.push(
      locationId
    );


  }


}





function getLocationHistory() {


  return locationHistory;


}

// =========================================
// LOCATION TRAVEL HISTORY INTEGRATION
// =========================================


function travelToLocation(
  locationId
) {


  if (
    !canTravelToLocation(
      locationId
    )
  ) {


    console.log(
      "Travel denied:",
      locationId
    );


    return false;


  }



  setPlayerLocation(
    locationId
  );



  recordLocationVisit(
    locationId
  );



  console.log(
    "Player travelled to:",
    locationId
  );



  return true;


}

