// =========================================


function getLocationAvailableActions(
  locationId
) {


  const location =
    getLocationData(
      locationId
    );


  if (!location) {

    return [];

  }


  const actions =
    [];


  if (
    isLocationDiscovered(
      locationId
    )
  ) {

    actions.push(
      "explore"
    );

  }


  if (
    locationHistory.includes(
      locationId
    )
  ) {

    actions.push(
      "revisit"
    );

  }


  return actions;


}

