// =========================================================
// LOCATION DISCOVERY COUNT
// =========================================================


function getDiscoveredLocationCount() {


  let count =
    0;


  for (
    const locationId in LOCATION_DATABASE
  ) {


    if (
      isLocationDiscovered(
        locationId
      )
    ) {

      count++;

    }


  }


  return count;


}

