// =========================================
// LOCATION DISCOVERY DISPLAY DATA
// =========================================

function getLocationDiscoveryDisplayData(
  locationId
) {


  const discovered =
    isLocationDiscovered(
      locationId
    );


  const location =
    getLocationData(
      locationId
    );


  if (!location) {

    return null;

  }


  return {

    id:
      location.id,

    name:
      location.name,

    discovered:
      discovered,

    status:
      discovered
        ? "DISCOVERED"
        : "UNDISCOVERED"

  };

}

// =========================================================
// LOCATION ACTION DISPLAY DATA
// =========================================================

function getLocationActionDisplayData(
  locationId
) {


  const actions =
    getLocationActions(
      locationId
    );


  if (!actions) {

    return [];

  }


  return actions.map(
    action => ({

      id:
        action,

      name:
        action
          .replace(
            /_/g,
            " "
          )
          .toUpperCase()

    })
  );

}

// =========================================================
// LOCATION SUMMARY BUILDER
// =========================================================

function getLocationDisplaySummary(
  locationId
) {


  const location =
    getLocationData(
      locationId
    );


  if (!location) {

    return null;

  }


  return {

    navigation:
      getLocationNavigationData(
        locationId
      ),

    discovery:
      getLocationDiscoveryDisplayData(
        locationId
      ),

    actions:
      getLocationActionDisplayData(
        locationId
      )

  };

}

// =========================================================
// LOCATION SUMMARY VALIDATION
// =========================================================

function validateLocationSummary(
  locationId
) {


  const summary =
    getLocationSummaryData(
      locationId
    );


  if (!summary) {

    return false;

  }


  return (

    !!summary.navigation &&

    !!summary.discovery &&

    Array.isArray(
      summary.actions
    )

  );

}




