// =========================================================
// LOCATION COMPLETION CHECK
// =========================================================

function isLocationComplete(
  locationId
) {


  const progress =
    getPlayerLocationProgress(
      locationId
    );


  if (
    !progress
  ) {

    return false;

  }


  return (
    progress.state ===
    "completed"
  );

}

// =========================================================
// LOCATION SYSTEM SUMMARY
// =========================================================

function getLocationSystemSummary() {


  return {

    totalLocations:
      Object.keys(
        LOCATION_DATABASE
      ).length,

    discovered:
      getDiscoveredLocations()
        .length,

    currentLocation:
      selectedLocationNode
        ? selectedLocationNode.id
        : null

  };

}

// =========================================================
// LOCATION DISCOVERY COUNT DATA
// =========================================================

function getLocationDiscoveryCount() {


  const locations =
    Object.keys(
      LOCATION_DATABASE
    );


  const discovered =
    locations.filter(
      locationId =>
        isLocationDiscovered(
          locationId
        )
    );


  return {

    total:
      locations.length,

    discovered:
      discovered.length

  };

}

// =========================================
// LOCATION VISIT COUNT DATA
// =========================================

function getLocationVisitCount() {


  const history =
    getLocationHistory();


  return {

    totalVisits:
      history.length,

    uniqueLocations:
      [
        ...new Set(
          history
        )
      ].length

  };

}

// =========================================================
// LOCATION PLAYER PROGRESS SUMMARY
// =========================================================

function getLocationPlayerProgressSummary(
  locationId
) {


  const progress =
    getPlayerLocationProgress(
      locationId
    );


  if (
    !progress
  ) {

    return null;

  }


  return {

    id:
      progress.id,

    name:
      progress.name,

    state:
      progress.state,

    discovered:
      progress.discovered,

    visited:
      progress.visited

  };

}

// =========================================================
// FULL LOCATION PLAYER SUMMARY
// =========================================================

function getPlayerLocationProgressSummary() {


  return {

    discovery:
      getLocationDiscoveryCount(),

    visits:
      getLocationVisitCount(),

    current:
      selectedLocationNode
        ? selectedLocationNode.id
        : null

  };

}

// =========================================================
// BRICK 131 — LOCATION ENGINE HEALTH CHECK
// =========================================================
//
// Non-destructive Location Engine diagnostics.
//
// Validates:
// - Location database
// - Discovery
// - History
// - Progress
// - Activity mappings
// - Location activity execution bridge
//
// =========================================================


function validateLocationSystem() {


  const checks = {


    database:
      Object.keys(
        LOCATION_DATABASE
      ).length > 0,


    discovery:
      typeof isLocationDiscovered ===
        "function",


    history:
      typeof getLocationHistory ===
        "function",


    progress:
      typeof getPlayerLocationProgress ===
        "function",


    activityConnections:
      typeof LOCATION_ACTIVITY_CONNECTIONS ===
        "object",


    activityLookup:
      typeof getLocationActivity ===
        "function",


    activityValidation:
      typeof validateLocationActivity ===
        "function",


    activityLaunch:
      typeof launchLocationAction ===
        "function",


    activityExecution:
      typeof executeLocationAction ===
        "function"


  };



  checks.healthy =
    Object.values(
      checks
    ).every(
      value =>
        value === true
    );



  console.log(
    "Location Engine health:",
    checks
  );



  return checks;


}

// =========================================================
// BRICK 132 — ACTIVITY ENGINE HEALTH CHECK
// =========================================================
//
// Non-destructive Activity Engine diagnostics.
//
// Validates:
// - Activity database
// - Result creation
// - Hydration
// - Reward processor
// - Progression router
// - Completion recording
// - Chronicle history
// - Player Loop bridge
//
// =========================================================


function validateActivitySystem() {


  const requiredActivities = [
    "exam",
    "practical",
    "battle",
    "mission"
  ];



  const registeredActivities =
    requiredActivities.every(
      activityId =>
        !!getActivityData(
          activityId
        )
    );



  const resultProbe =
    createActivityResult(
      "practical",
      "naruto"
    );



  const normalizedResult =
    !!(
      resultProbe &&
      resultProbe.rewards &&
      Array.isArray(
        resultProbe.rewards.items
      ) &&
      Array.isArray(
        resultProbe.rewards.progression
      )
    );



  const checks = {


    database:
      typeof ACTIVITY_DATABASE ===
        "object",


    registeredActivities:
      registeredActivities,


    resolution:
      typeof resolveActivityAction ===
        "function",


    resultFoundation:
      normalizedResult,


    hydration:
      typeof hydrateActivityResult ===
        "function",


    rewardProcessor:
      typeof applyActivityRewards ===
        "function",


    progression:
      typeof processActivityProgression ===
        "function",


    completion:
      typeof recordActivityCompletion ===
        "function",


    history:
      typeof getActivityHistory ===
        "function",


    analytics:
      typeof getActivityAnalytics ===
        "function",


    registeredExecution:
      typeof startRegisteredActivity ===
        "function",


    playerLoop:
      typeof executePlayerActivity ===
        "function"


  };



  checks.healthy =
    Object.values(
      checks
    ).every(
      value =>
        value === true
    );



  console.log(
    "Activity Engine health:",
    checks
  );



  return checks;


}

// =========================================================
// BRICK 151 — ENCOUNTER BATTLE BRIDGE DIAGNOSTICS
// =========================================================
//
// Structural diagnostics only.
//
// Does NOT launch combat.
//
// =========================================================


function validateEncounterBattleBridge() {


  const scoutEncounter =
    getEncounterDefinition(
      "scout_patrol"
    );


  const naruto =
    getPlayerCharacter(
      "naruto"
    );


  const checks = {


    battleState:
      (
        typeof currentBattle ===
          "object" &&
        currentBattle !==
          null
      ),


    battleLauncher:
      typeof startEncounter ===
        "function",


    encounterLauncher:
      typeof startEncounterActivity ===
        "function",


    encounterContext:
      (
        Object.prototype.hasOwnProperty.call(
          currentBattle,
          "encounterId"
        ) &&
        Object.prototype.hasOwnProperty.call(
          currentBattle,
          "characterId"
        )
      ),


    encounterDefinition:
      !!scoutEncounter,


    enemyLink:
      !!(
        scoutEncounter &&
        enemyDatabase[
          scoutEncounter.enemyId
        ]
      ),


    characterResolution:
      !!naruto


  };


  checks.healthy =
    Object.values(
      checks
    ).every(
      value =>
        value === true
    );


  console.log(
    "Encounter Battle Bridge health:",
    checks
  );


  return checks;


}

// =========================================================
// BRICK 147 — ENCOUNTER ENGINE HEALTH CHECK
// =========================================================
//
// Non-destructive Encounter Engine diagnostics.
//
// =========================================================


function validateEncounterSystem() {


  const requiredEncounters = [

    "scout_patrol",
    "bandit_leader",
    "hidden_cache"

  ];



  const registered =
    requiredEncounters.every(
      encounterId =>
        !!getEncounterData(
          encounterId
        )
    );



  const definitions =
    requiredEncounters.every(
      encounterId =>
        !!getEncounterDefinition(
          encounterId
        )
    );



  const enemyLinks =
    requiredEncounters.every(
      encounterId => {


        const encounter =
          getEncounterDefinition(
            encounterId
          );



        return !!(
          encounter &&
          encounter.enemy &&
          enemyDatabase[
            encounter.enemyId
          ]
        );


      }
    );



  const checks = {


    database:
      typeof ENCOUNTER_DATABASE ===
        "object",


    registered:
      registered,


    definitions:
      definitions,


    enemyLinks:
      enemyLinks,


    normalizer:
      typeof normalizeEncounterDefinition ===
        "function",


    readiness:
      typeof getEncounterReadiness ===
        "function",


    execution:
      typeof startEncounterActivity ===
        "function",


    battleAuthority:
      typeof startEncounter ===
        "function"


  };



  checks.healthy =
    Object.values(
      checks
    ).every(
      value =>
        value === true
    );



  console.log(
    "Encounter Engine health:",
    checks
  );



  return checks;


}

