// =========================================================
// BRICK 203 — KONOHA SERVICE EXECUTION REQUEST
// =========================================================
//
// Normalizes one Konoha service launch request.
//
// =========================================================


function createKonohaServiceRequest(
  serviceId,
  characterId
) {


  return {

    serviceId:
      serviceId || null,

    characterId:
      characterId || null,

    timestamp:
      Date.now()

  };


}



// =========================================================
// BRICK 204 — KONOHA SERVICE REQUEST VALIDATION
// =========================================================


function validateKonohaServiceRequest(
  request
) {


  if (
    !request ||
    !request.serviceId
  ) {


    return {

      valid:
        false,

      reason:
        "invalid_service_request"

    };


  }


  const service =
    getKonohaService(
      request.serviceId
    );


  if (
    !service
  ) {


    return {

      valid:
        false,

      reason:
        "unknown_konoha_service",

      serviceId:
        request.serviceId

    };


  }


  const access =
    evaluateKonohaServiceAccess(
      request.serviceId
    );


  if (
    access.implemented !==
      true
  ) {


    return {

      valid:
        false,

      reason:
        "service_not_implemented",

      service:
        service,

      access:
        access

    };


  }


  if (
    access.accessible !==
      true
  ) {


    return {

      valid:
        false,

      reason:
        "service_locked",

      service:
        service,

      access:
        access

    };


  }


  const character =
    getPlayerCharacter(
      request.characterId
    );


  if (
    !character
  ) {


    return {

      valid:
        false,

      reason:
        "invalid_character",

      service:
        service,

      access:
        access

    };


  }


  return {

    valid:
      true,

    reason:
      null,

    service:
      service,

    access:
      access,

    character:
      character

  };


}



// =========================================================
// BRICK 205 — KONOHA ACTIVITY SERVICE EXECUTOR
// =========================================================
//
// Routes:
//
// - Missions
// - Exams
// - Practical
//
// through the existing Location → Activity authority.
//
// =========================================================


function executeKonohaActivityService(
  service,
  characterId
) {


  if (
    !service ||
    service.routeType !==
      "activity"
  ) {


    return false;


  }


  return launchLocationAction(

    "konoha",

    service.action,

    characterId

  );


}



// =========================================================
// BRICK 206 — KONOHA TRAINING SERVICE EXECUTOR
// =========================================================
//
// Dedicated Training remains owned by
// the Training Engine.
//
// =========================================================


function executeKonohaTrainingService(
  service,
  characterId
) {


  if (
    !service ||
    service.routeType !==
      "training" ||
    !service.trainingId
  ) {


    return false;


  }


  return startTraining(

    service.trainingId,

    characterId

  );


}



// =========================================================
// BRICK 207 — KONOHA SERVICE ROUTER
// =========================================================
//
// One execution authority for Konoha services.
//
// =========================================================


function routeKonohaServiceExecution(
  service,
  characterId
) {


  if (
    !service
  ) {


    return false;


  }


  switch (
    service.routeType
  ) {


    case "activity":


      return executeKonohaActivityService(
        service,
        characterId
      );



    case "training":


      return executeKonohaTrainingService(
        service,
        characterId
      );



    default:


      console.log(
        "Unsupported Konoha service route:",
        service.routeType
      );


      return false;


  }


}



// =========================================================
// BRICK 208 — KONOHA SERVICE EXECUTION RESULT
// =========================================================
//
// UI-safe result returned after execution.
//
// =========================================================


function createKonohaServiceExecutionResult(
  request,
  validation,
  executionResult
) {


  const success =
    !!executionResult;


  return {

    success:
      success,

    serviceId:
      request.serviceId,

    characterId:
      request.characterId,

    routeType:
      validation.service
        ? validation.service.routeType
        : null,

    activityId:
      validation.service &&
      validation.service.activityId
        ? validation.service.activityId
        : null,

    trainingId:
      validation.service &&
      validation.service.trainingId
        ? validation.service.trainingId
        : null,

    result:
      executionResult || null

  };


}



// =========================================================
// BRICK 209 — KONOHA SERVICE EXECUTION PREVIEW
// =========================================================
//
// Non-destructive UI / diagnostic preview.
//
// =========================================================


function getKonohaServiceExecutionPreview(
  serviceId,
  characterId
) {


  const request =
    createKonohaServiceRequest(
      serviceId,
      characterId
    );


  const validation =
    validateKonohaServiceRequest(
      request
    );


  return {

    request:
      request,

    valid:
      validation.valid ===
        true,

    reason:
      validation.reason ||
      null,

    service:
      validation.service ||
      getKonohaService(
        serviceId
      ),

    access:
      validation.access ||
      evaluateKonohaServiceAccess(
        serviceId
      ),

    character:
      validation.character
        ? {

            id:
              validation.character.id,

            name:
              validation.character.name,

            rank:
              validation.character.rank,

            currentPL:
              calculateCurrentPL(
                validation.character
              )

          }
        : null

  };


}



// =========================================================
// BRICK 210 — EXECUTE KONOHA SERVICE
// =========================================================
//
// Canonical Konoha UI launch function.
//
// Future UI buttons should call THIS,
// not individual engines directly.
//
// =========================================================


function executeKonohaService(
  serviceId,
  characterId
) {


  const request =
    createKonohaServiceRequest(
      serviceId,
      characterId
    );


  const validation =
    validateKonohaServiceRequest(
      request
    );


  if (
    validation.valid !==
      true
  ) {


    console.log(
      "Konoha service execution rejected:",
      validation
    );


    return {

      success:
        false,

      serviceId:
        serviceId || null,

      characterId:
        characterId || null,

      reason:
        validation.reason ||
        "service_execution_rejected"

    };


  }


  console.log(
    "KONOHA SERVICE START:",
    serviceId,
    characterId
  );


  const executionResult =
    routeKonohaServiceExecution(

      validation.service,

      characterId

    );


  const result =
    createKonohaServiceExecutionResult(

      request,

      validation,

      executionResult

    );


  console.log(
    "KONOHA SERVICE COMPLETE:",
    result
  );


  return result;


}



// =========================================================
// BRICK 211 — KONOHA SERVICE EXECUTION HEALTH CHECK
// =========================================================
//
// Non-destructive diagnostics.
//
// =========================================================


function validateKonohaServiceExecutionSystem() {


  const examPreview =
    getKonohaServiceExecutionPreview(
      "exams",
      "naruto"
    );


  const practicalPreview =
    getKonohaServiceExecutionPreview(
      "practical",
      "naruto"
    );


  const trainingPreview =
    getKonohaServiceExecutionPreview(
      "training",
      "naruto"
    );


  const shopPreview =
    getKonohaServiceExecutionPreview(
      "shop",
      "naruto"
    );


  const invalidCharacterPreview =
    getKonohaServiceExecutionPreview(
      "exams",
      "not_a_character"
    );


  const checks = {


    requestBuilder:
      !!createKonohaServiceRequest(
        "exams",
        "naruto"
      ),


    validator:
      examPreview.valid ===
        true,


    activityExecutor:
      typeof executeKonohaActivityService ===
        "function",


    trainingExecutor:
      typeof executeKonohaTrainingService ===
        "function",


    router:
      typeof routeKonohaServiceExecution ===
        "function",


    resultBuilder:
      typeof createKonohaServiceExecutionResult ===
        "function",


    preview:
      typeof getKonohaServiceExecutionPreview ===
        "function",


    executionAuthority:
      typeof executeKonohaService ===
        "function",


    examReady:
      examPreview.valid ===
        true,


    practicalReady:
      practicalPreview.valid ===
        true,


    trainingReady:
      trainingPreview.valid ===
        true,


    shopSafelyBlocked:
      (
        shopPreview.valid ===
          false &&
        shopPreview.reason ===
          "service_not_implemented"
      ),


    invalidCharacterBlocked:
      (
        invalidCharacterPreview.valid ===
          false &&
        invalidCharacterPreview.reason ===
          "invalid_character"
      )


  };


  checks.healthy =
    Object.values(
      checks
    ).every(
      value =>
        value === true
    );


  console.log(
    "Konoha Service Execution health:",
    checks
  );


  return checks;


}



// =========================================================
// BRICK 213 — KONOHA ACTIVITY UI SESSION STATE
// =========================================================
//
// Runtime-only UI state.
//
// Tracks:
//
// - Current Exam / Practical screen
// - Currently selected Shinobi
//
// Gameplay progression remains owned by the
// existing Activity / Character systems.
//
// =========================================================


const KONOHA_ACTIVITY_UI_SERVICES = [

  "exams",
  "practical"

];


const KONOHA_ACTIVITY_UI_STATE = {

  serviceId:
    null,

  characterId:
    null

};



function getKonohaActivityUISessionState() {


  return {

    serviceId:
      KONOHA_ACTIVITY_UI_STATE
        .serviceId,

    characterId:
      KONOHA_ACTIVITY_UI_STATE
        .characterId

  };


}



// =========================================================
// BRICK 214 — KONOHA SELECTABLE SHINOBI QUERY
// =========================================================
//
// Uses playerTeam as the current roster authority.
//
// Does NOT create a duplicate character database.
//
// =========================================================


function getKonohaSelectableCharacters() {


  return playerTeam
    .filter(
      character =>
        character &&
        character.id
    )
    .map(
      character => ({


        id:
          character.id,


        name:
          character.name,


        rank:
          character.rank,


        rarity:
          character.rarity ||
          null,


        image:
          character.image ||
          null,


        currentPL:
          calculateCurrentPL(
            character
          )


      })
    );


}



// =========================================================
// BRICK 215 — OPEN KONOHA ACTIVITY UI SESSION
// =========================================================
//
// Establishes the screen and selected character.
//
// If no character is supplied,
// the first selectable Shinobi is used.
//
// =========================================================


function openKonohaActivityUIScreen(
  serviceId,
  characterId = null
) {


  if (
    !KONOHA_ACTIVITY_UI_SERVICES
      .includes(
        serviceId
      )
  ) {


    return {

      success:
        false,

      reason:
        "unsupported_activity_ui_service"

    };


  }


  const characters =
    getKonohaSelectableCharacters();


  if (
    characters.length ===
      0
  ) {


    return {

      success:
        false,

      reason:
        "no_selectable_characters"

    };


  }


  let selectedCharacterId =
    characterId;


  if (
    !selectedCharacterId
  ) {


    selectedCharacterId =
      characters[0].id;


  }


  const character =
    getPlayerCharacter(
      selectedCharacterId
    );


  if (
    !character
  ) {


    return {

      success:
        false,

      reason:
        "invalid_character"

    };


  }


  KONOHA_ACTIVITY_UI_STATE
    .serviceId =
      serviceId;


  KONOHA_ACTIVITY_UI_STATE
    .characterId =
      character.id;


  return {

    success:
      true,

    serviceId:
      serviceId,

    characterId:
      character.id

  };


}



// =========================================================
// BRICK 216 — KONOHA SHINOBI SELECTION CONTROL
// =========================================================
//
// Supports:
//
// - Direct character selection
// - Previous / Next character cycling
//
// Used by the CHANGE SHINOBI control.
//
// =========================================================


function setKonohaSelectedCharacter(
  characterId
) {


  const character =
    getPlayerCharacter(
      characterId
    );


  if (
    !character
  ) {


    return false;


  }


  KONOHA_ACTIVITY_UI_STATE
    .characterId =
      character.id;


  return true;


}



function cycleKonohaSelectedCharacter(
  direction = 1
) {


  const characters =
    getKonohaSelectableCharacters();


  if (
    characters.length ===
      0
  ) {


    return null;


  }


  const currentId =
    KONOHA_ACTIVITY_UI_STATE
      .characterId;


  let currentIndex =
    characters.findIndex(
      character =>
        character.id ===
          currentId
    );


  if (
    currentIndex <
      0
  ) {


    currentIndex =
      0;


  }


  const step =
    Number(direction) <
      0
      ? -1
      : 1;


  const nextIndex =
    (
      currentIndex +
      step +
      characters.length
    ) %
    characters.length;


  const nextCharacter =
    characters[
      nextIndex
    ];


  KONOHA_ACTIVITY_UI_STATE
    .characterId =
      nextCharacter.id;


  return nextCharacter;


}



// =========================================================
// BRICK 217 — SELECTED SHINOBI UI PROFILE
// =========================================================
//
// Left-side character panel contract.
//
// Current PL:
// persistent Developed Stats.
//
// PL Progress:
// continuous progress through the current Raw PL interval.
//
// Effective PL remains excluded from this UI profile.
//
// Village / Clan / Element / Status remain null until
// proper canonical metadata authorities are added.
//
// =========================================================


function getKonohaCharacterUIProfile(
  characterId
) {


  const character =
    getPlayerCharacter(
      characterId
    );


  if (
    !character
  ) {


    return null;

  }


  const plProgress =
    getCharacterPLProgress(
      character
    );


  return {


    id:
      character.id,


    name:
      character.name,


    rank:
      character.rank,


    rarity:
      character.rarity ||
      null,


    currentPL:
      plProgress.displayedPL,


    plProgress: {

      rawPL:
        plProgress.rawPL,

      currentPL:
        plProgress.displayedPL,

      nextPL:
        plProgress.nextPL,

      progress:
        plProgress.progress,

      progressPercent:
        plProgress.progressPercent

    },


    image:
      character.image ||
      null,


    village:
      character.village ||
      null,


    clan:
      character.clan ||
      null,


    element:
      character.element ||
      null,


    status:
      character.status ||
      null


  };

}



// =========================================================
// BRICK 218 — DISCIPLINE UI PANEL NORMALIZER
// =========================================================
//
// Converts canonical Discipline progression into
// renderer-ready progress data.
//
// =========================================================


function getKonohaDisciplineUIPanelData(
  discipline
) {


  if (
    !discipline
  ) {


    return null;


  }


  const currentExp =
    Math.max(
      0,
      Number(
        discipline.exp
      ) || 0
    );


  const expRequired =
    Math.max(
      0,
      Number(
        discipline.expRequired
      ) || 0
    );


  const progressPercent =
    expRequired >
      0

      ? Math.min(
          100,
          Math.max(
            0,
            (
              currentExp /
              expRequired
            ) *
            100
          )
        )

      : 0;


  return {


    id:
      discipline.id,


    name:
      discipline.name,


    level:
      Number(
        discipline.level
      ) || 1,


    exp:
      currentExp,


    expRequired:
      expRequired,


    expRemaining:
      Math.max(
        0,
        expRequired -
          currentExp
      ),


    progressPercent:
      progressPercent,


    rewardExp:
      Math.max(
        0,
        Number(
          discipline.rewardExp
        ) || 0
      )


  };


}



// =========================================================
// BRICK 219 — ACTIVITY ELIGIBILITY UI CONTRACT
// =========================================================
//
// Converts existing service/access authority into
// UI-safe eligibility state.
//
// IMPORTANT:
//
// Mock-up fields such as:
//
// - Rank Requirement
// - Level Requirement
// - Active Mission Limit
// - Cooldown
//
// are NOT invented here.
//
// They remain unconfigured until their real
// gameplay rules are formally defined.
//
// =========================================================


function getKonohaActivityEligibilityUIData(
  serviceId,
  characterId
) {


  const preview =
    getKonohaServiceExecutionPreview(
      serviceId,
      characterId
    );


  const access =
    preview &&
    preview.access
      ? preview.access
      : null;


  const requirementResults =
    access &&
    access.evaluation &&
    Array.isArray(
      access.evaluation.results
    )

      ? access.evaluation.results

      : [];


  return {


    eligible:
      !!(
        preview &&
        preview.valid ===
          true
      ),


    reason:
      preview
        ? preview.reason
        : "preview_unavailable",


    requirements:
      requirementResults,


    criteria: {


      rankRequirement:
        null,


      levelRequirement:
        null,


      activeMissionLimit:
        null,


      cooldown:
        null


    },


    criteriaConfigured:
      false


  };


}



// =========================================================
// BRICK 220 — EXAM UI SCREEN DATA COMPOSER
// =========================================================
//
// Complete renderer contract for Shinobi Exams.
//
// =========================================================


function getKonohaExamUIScreenData(
  characterId = null
) {


  const selectedCharacterId =
    characterId ||
    KONOHA_ACTIVITY_UI_STATE
      .characterId;


  if (
    !selectedCharacterId
  ) {


    return null;


  }


  const pageData =
    getKonohaExamPageData(
      selectedCharacterId
    );


  const profile =
    getKonohaCharacterUIProfile(
      selectedCharacterId
    );


  if (
    !pageData ||
    !profile
  ) {


    return null;


  }


  const disciplines =
    pageData.activity
      .disciplines
      .map(
        discipline =>
          getKonohaDisciplineUIPanelData(
            discipline
          )
      )
      .filter(
        discipline =>
          !!discipline
      );


  const eligibility =
    getKonohaActivityEligibilityUIData(
      "exams",
      selectedCharacterId
    );


  return {


    screen:
      "exams",


    title:
      pageData.title,


    selectedCharacterId:
      selectedCharacterId,


    characters:
      getKonohaSelectableCharacters(),


    character:
      profile,


    disciplines:
      disciplines,


    eligibility:
      eligibility,


    canExecute:
      eligibility.eligible ===
        true,


    service:
      pageData.service


  };


}



// =========================================================
// BRICK 221 — PRACTICAL UI SCREEN DATA COMPOSER
// =========================================================
//
// Complete renderer contract for Practical Training.
//
// =========================================================


function getKonohaPracticalUIScreenData(
  characterId = null
) {


  const selectedCharacterId =
    characterId ||
    KONOHA_ACTIVITY_UI_STATE
      .characterId;


  if (
    !selectedCharacterId
  ) {


    return null;


  }


  const pageData =
    getKonohaPracticalPageData(
      selectedCharacterId
    );


  const profile =
    getKonohaCharacterUIProfile(
      selectedCharacterId
    );


  if (
    !pageData ||
    !profile
  ) {


    return null;


  }


  const disciplines =
    pageData.activity
      .disciplines
      .map(
        discipline =>
          getKonohaDisciplineUIPanelData(
            discipline
          )
      )
      .filter(
        discipline =>
          !!discipline
      );


  const eligibility =
    getKonohaActivityEligibilityUIData(
      "practical",
      selectedCharacterId
    );


  return {


    screen:
      "practical",


    title:
      pageData.title,


    selectedCharacterId:
      selectedCharacterId,


    characters:
      getKonohaSelectableCharacters(),


    character:
      profile,


    disciplines:
      disciplines,


    eligibility:
      eligibility,


    canExecute:
      eligibility.eligible ===
        true,


    service:
      pageData.service


  };


}



// =========================================================
// BRICK 222 — EXAM / PRACTICAL UI DATA HEALTH CHECK
// =========================================================
//
// Non-destructive UI contract diagnostics.
//
// =========================================================


function validateKonohaActivityUIDataSystem() {


  const originalState =
    getKonohaActivityUISessionState();


  const opened =
    openKonohaActivityUIScreen(
      "exams",
      "naruto"
    );


  const characters =
    getKonohaSelectableCharacters();


  const profile =
    getKonohaCharacterUIProfile(
      "naruto"
    );


  const exam =
    getKonohaExamUIScreenData(
      "naruto"
    );


  const practical =
    getKonohaPracticalUIScreenData(
      "naruto"
    );


  const eligibility =
    getKonohaActivityEligibilityUIData(
      "exams",
      "naruto"
    );


  const checks = {


    sessionState:
      typeof KONOHA_ACTIVITY_UI_STATE ===
        "object",


    sessionOpen:
      opened.success ===
        true,


    selectableCharacters:
      (
        Array.isArray(
          characters
        ) &&
        characters.length >
          0
      ),


    characterProfile:
      !!(
        profile &&
        profile.id ===
          "naruto"
      ),


    examScreen:
      !!(
        exam &&
        exam.screen ===
          "exams" &&
        exam.disciplines.length ===
          3
      ),


    practicalScreen:
      !!(
        practical &&
        practical.screen ===
          "practical" &&
        practical.disciplines.length ===
          3
      ),


    examProgress:
      exam &&
      exam.disciplines.every(
        discipline =>
          Number.isFinite(
            discipline.progressPercent
          )
      ),


    practicalProgress:
      practical &&
      practical.disciplines.every(
        discipline =>
          Number.isFinite(
            discipline.progressPercent
          )
      ),


    eligibility:
      eligibility.eligible ===
        true,


    selectionControl:
      typeof cycleKonohaSelectedCharacter ===
        "function"


  };


  checks.healthy =
    Object.values(
      checks
    ).every(
      value =>
        value === true
    );


  KONOHA_ACTIVITY_UI_STATE
    .serviceId =
      originalState.serviceId;


  KONOHA_ACTIVITY_UI_STATE
    .characterId =
      originalState.characterId;


  console.log(
    "Konoha Activity UI Data health:",
    checks
  );


  return checks;


}


// =========================================================
// BRICK 223 — KONOHA ACTIVITY SCREEN RENDERER FOUNDATION
// =========================================================
//
// Presentation authority for the Konoha Exam / Practical UI.
//
// IMPORTANT:
//
// This layer does NOT own:
// - progression
// - rewards
// - eligibility
// - character data
// - activity execution
//
// It consumes the existing Konoha Activity UI data layer.
//
// =========================================================


function getKonohaActivityUIScreenData(
  serviceId
) {


  const session =
    getKonohaActivityUISessionState();


  const selectedCharacterId =
    session.characterId;


  if (
    serviceId === "exams"
  ) {


    return getKonohaExamUIScreenData(
      selectedCharacterId
    );


  }


  if (
    serviceId === "practical"
  ) {


    return getKonohaPracticalUIScreenData(
      selectedCharacterId
    );


  }


  return null;


}


// =========================================================
// KONOHA ACTIVITY UI ROOT QUERY
// =========================================================


function getKonohaActivityUIRoot() {


  return document.getElementById(
    "konoha-activity-screen"
  );


}


// =========================================================
// KONOHA ACTIVITY UI ROOT CREATOR
// =========================================================


function ensureKonohaActivityUIRoot() {


  let root =
    getKonohaActivityUIRoot();


  if (root) {


    return root;


  }


  root =
    document.createElement(
      "div"
    );


  root.id =
    "konoha-activity-screen";


  root.className =
    "konoha-activity-screen";


  root.style.display =
    "none";


  document.body.appendChild(
    root
  );


  return root;


}


// =========================================================
// KONOHA ACTIVITY UI CLEAR
// =========================================================


function clearKonohaActivityUIScreen() {


  const root =
    getKonohaActivityUIRoot();


  if (!root) {


    return false;


  }


  root.innerHTML =
    "";


  return true;


}


// =========================================================
// KONOHA ACTIVITY UI CLOSE
// =========================================================


function closeKonohaActivityUIScreen() {


  const root =
    getKonohaActivityUIRoot();


  if (root) {


    root.innerHTML =
      "";


    root.style.display =
      "none";


    delete root.dataset.serviceId;


  }


  KONOHA_ACTIVITY_UI_STATE
    .serviceId =
      null;


  KONOHA_ACTIVITY_UI_STATE
    .characterId =
      null;


  return true;


}


// =========================================================
// KONOHA ACTIVITY UI FOUNDATION RENDERER
// =========================================================


function renderKonohaActivityUIScreen(
  serviceId
) {


  const root =
    ensureKonohaActivityUIRoot();


  const data =
    getKonohaActivityUIScreenData(
      serviceId
    );


  if (!data) {


    console.log(
      "Konoha Activity UI render failed:",
      serviceId
    );


    return false;


  }


  root.innerHTML =
    "";


  root.dataset.serviceId =
    serviceId;


  root.style.display =
    "block";


  const shell =
    document.createElement(
      "div"
    );


  shell.className =
    "konoha-activity-shell";


  shell.dataset.screen =
    data.screen;


  root.appendChild(
    shell
  );


  console.log(
    "KONOHA ACTIVITY UI RENDER:",
    {
      serviceId:
        serviceId,

      screen:
        data.screen,

      characterId:
        data.selectedCharacterId
    }
  );


  return true;


}


// =========================================================
// BRICK 304 — KONOHA ACTIVITY UI OPEN + RENDER ROUTER
// =========================================================
//
// Canonical Activity UI entry point.
//
// Specialised visual screens take priority.
// Generic renderer remains as safe fallback.
//
// =========================================================


function showKonohaActivityUIScreen(
  serviceId,
  characterId
) {


  // =========================================
  // SHINOBI EXAMS
  // =========================================

  if (
    serviceId ===
      "exams"
  ) {


    return showKonohaExamUIScreen(
      characterId
    );


  }


  // =========================================
  // PRACTICAL TRAINING
  // =========================================

  if (
    serviceId ===
      "practical"
  ) {


    return showKonohaPracticalUIScreen(
      characterId
    );


  }


  // =========================================
  // GENERIC FALLBACK
  // =========================================

  const sessionResult =
    openKonohaActivityUIScreen(
      serviceId,
      characterId
    );


  if (
    !sessionResult ||
    sessionResult.success !==
      true
  ) {


    return sessionResult;


  }


  const rendered =
    renderKonohaActivityUIScreen(
      serviceId
    );


  return {


    success:
      rendered === true,


    serviceId:
      serviceId,


    characterId:
      getKonohaActivityUISessionState()
        .characterId,


    rendered:
      rendered === true


  };


}



// =========================================================
// BRICK 224 — SHINOBI EXAMS STYLE AUTHORITY BRIDGE
// =========================================================
//
// Exam presentation is now owned by style.css.
//
// This bridge preserves the existing runtime style authority
// contract without injecting obsolete Exam presentation CSS.
//
// Owns:
// - style authority identity
//
// Does NOT own:
// - Exam geometry
// - character-card presentation
// - discipline presentation
// - BEGIN EXAM presentation
// - batch controls
// - result presentation
// - retired Eligibility / lower-panel / bottom-nav styling
//
