// =========================================================
// BRICK 303 — EXAM RENDERED VISUAL HEALTH CONTRACT
// =========================================================
//
// Validates the Exam screen AFTER it has been rendered.
//
// Owns checks for:
// - required live DOM
// - discipline presentation count
// - live progression presentation
// - progress-track containment
// - batch controls
// - BEGIN EXAM
// - Konoha return
//
// Does NOT validate:
// - gameplay resolution
// - progression mathematics
// - Chronicle history
// - access architecture
//
// Those remain owned by their dedicated systems.
//
// =========================================================

function validateKonohaExamVisualSystem() {


  const root =
    getKonohaActivityUIRoot();


  const examScreen =
    root &&
    root.querySelector(
      ".konoha-exam-screen"
    );


  const characterPanel =
    root &&
    root.querySelector(
      ".exam-character-panel"
    );


  const characterImage =
    root &&
    root.querySelector(
      ".exam-character-image"
    );


  const disciplineCards =
    root
      ? Array.from(
          root.querySelectorAll(
            ".exam-discipline-card"
          )
        )
      : [];


  const progressTracks =
    root
      ? Array.from(
          root.querySelectorAll(
            ".exam-progress-track"
          )
        )
      : [];


  const masteryValues =
    root
      ? root.querySelectorAll(
          ".exam-mastery-value"
        ).length
      : 0;


  const expLabels =
    root
      ? root.querySelectorAll(
          ".exam-discipline-exp-label"
        ).length
      : 0;


  const expValues =
    root
      ? root.querySelectorAll(
          ".exam-discipline-exp-value"
        ).length
      : 0;


  const tracksContained =
    progressTracks.every(
      (
        track,
        index
      ) => {


        const card =
          disciplineCards[
            index
          ];


        if (!card) {

          return false;

        }


        const trackRect =
          track.getBoundingClientRect();


        const cardRect =
          card.getBoundingClientRect();


        return (
          trackRect.left >=
            cardRect.left &&
          trackRect.right <=
            cardRect.right &&
          trackRect.top >=
            cardRect.top &&
          trackRect.bottom <=
            cardRect.bottom
        );


      }
    );


  const batchControls =
    !!(
      root &&
      root.querySelector(
        ".exam-batch-controls"
      )
    );


  const beginButton =
    !!(
      root &&
      root.querySelector(
        ".exam-begin-button"
      )
    );


  const konohaReturn =
    !!(
      root &&
      root.querySelector(
        ".exam-konoha-return"
      )
    );


  /*
     Retired Exam presentation is intentionally outside
     the active visual-health contract.
  */


  const health = {


    screenPresent:
      !!root,


    examScreen:
      !!examScreen,


    characterPanel:
      !!characterPanel,


    characterImage:
      !!characterImage,


    disciplineCards:
      disciplineCards.length ===
        3,


    masteryValues:
      masteryValues ===
        3,


    expLabels:
      expLabels ===
        3,


    expValues:
      expValues ===
        3,


    progressBars:
      progressTracks.length ===
        3,


    progressBarsContained:
      tracksContained,


    batchControls:
      batchControls,


    beginButton:
      beginButton,


        konohaReturn:
      konohaReturn,




    navigationFunctions:
      (
        typeof openKonohaExamFromVillage ===
          "function" &&
        typeof returnToKonohaFromActivityUI ===
          "function" &&
        typeof renderVillageOverlay ===
          "function"
      )


  };


  health.healthy =
    Object.values(
      health
    ).every(
      value =>
        value === true
    );


  console.log(
    "FINAL KONOHA EXAM VISUAL HEALTH:",
    health
  );


  return health;


}


// =========================================================
// BRICK 273B — CHRONICLE GAMEPLAY INTEGRATION REGRESSION
// =========================================================


function runActivityLocationRegression() {


  const contentAccessHealth =
    validateContentAccessSystem();


  const konohaDataHealth =
    validateKonohaDataBridge();


  const konohaExecutionHealth =
    validateKonohaServiceExecutionSystem();


  const konohaActivityUIHealth =
    validateKonohaActivityUIDataSystem();


  const locationHealth =
    validateLocationSystem();


  const activityHealth =
    validateActivitySystem();


  const trainingHealth =
    validateTrainingSystem();


  const encounterHealth =
    validateEncounterSystem();


  const battleBridgeHealth =
    validateEncounterBattleBridge();


  const battleCompletionHealth =
    validateBattleCompletionSystem();


  const battleQueryHealth =
    validateBattleChronicleQueries();


  const examGameplayHealth =
    validateKonohaExamGameplaySystem();


  // =========================================
  // LOCATION → ACTIVITY
  // =========================================


  const mappingChecks = {


    konohaMission:
      getLocationActivity(
        "konoha",
        "missions"
      ) ===
        "mission",


    konohaExam:
      getLocationActivity(
        "konoha",
        "exams"
      ) ===
        "exam",


    konohaPractical:
      getLocationActivity(
        "konoha",
        "practical"
      ) ===
        "practical",


    trainingGrounds:
      getLocationActivity(
        "training_grounds",
        "practical"
      ) ===
        "practical",


    rogueBattle:
      getLocationActivity(
        "rogue_hideout",
        "battle"
      ) ===
        "battle"


  };


  const mappingsHealthy =
    Object.values(
      mappingChecks
    ).every(
      value =>
        value === true
    );


  // =========================================
  // CHARACTER BRIDGE
  // =========================================


  const characterBridgeHealthy =
    !!getPlayerCharacter(
      "naruto"
    );


  // =========================================
  // TRAINING NORMALIZATION
  // =========================================


  const trainingProbe =
    normalizeTrainingActivityDefinition(
      getTrainingActivityData(
        "light_training"
      )
    );


  const trainingNormalizationHealthy =
    !!(
      trainingProbe &&
      trainingProbe.id ===
        "light_training" &&
      Array.isArray(
        trainingProbe.rewards
      )
    );


  // =========================================
  // ENCOUNTER NORMALIZATION
  // =========================================


  const encounterProbe =
    getEncounterDefinition(
      "scout_patrol"
    );


  const encounterNormalizationHealthy =
    !!(
      encounterProbe &&
      encounterProbe.enemyId ===
        "scout" &&
      encounterProbe.enemy &&
      encounterProbe.rewards
    );


  // =========================================
  // FINAL RESULT
  // =========================================


  const result = {


    locationEngine:
      locationHealth.healthy,


    activityEngine:
      activityHealth.healthy,


    trainingEngine:
      trainingHealth.healthy,


    encounterEngine:
      encounterHealth.healthy,


    battleBridge:
      battleBridgeHealth.healthy,


    battleCompletion:
      battleCompletionHealth.healthy,


    battleQueries:
      battleQueryHealth.healthy,


    examGameplay:
      examGameplayHealth.healthy,


    contentAccess:
      contentAccessHealth.healthy,


    konohaDataBridge:
      konohaDataHealth.healthy,


    konohaExecution:
      konohaExecutionHealth.healthy,


    konohaActivityUI:
      konohaActivityUIHealth.healthy,


    mappings:
      mappingsHealthy,


    characterBridge:
      characterBridgeHealthy,


    trainingNormalization:
      trainingNormalizationHealthy,


    encounterNormalization:
      encounterNormalizationHealthy,


    healthy:
      (
        locationHealth.healthy &&
        activityHealth.healthy &&
        trainingHealth.healthy &&
        encounterHealth.healthy &&
        battleBridgeHealth.healthy &&
        battleCompletionHealth.healthy &&
        battleQueryHealth.healthy &&
        examGameplayHealth.healthy &&
        contentAccessHealth.healthy &&
        konohaDataHealth.healthy &&
        konohaExecutionHealth.healthy &&
        konohaActivityUIHealth.healthy &&
        mappingsHealthy &&
        characterBridgeHealthy &&
        trainingNormalizationHealthy &&
        encounterNormalizationHealthy
      )


  };


  console.log(
    "========================================"
  );


  console.log(
    "CHRONICLE GAMEPLAY INTEGRATION REGRESSION"
  );


  console.table(
    mappingChecks
  );


  console.log(
    "Integration result:",
    result
  );


  console.log(
    "========================================"
  );


  return result;


}



// =========================================================
// BRICK 140 — LEGACY TRAINING DATA BRIDGE RETIRED
// =========================================================

// =========================================================
// TRAINING DATA VALIDATION
// =========================================================

function validateTrainingActivity(
  activityId
) {


  const activity =
    getTrainingActivityData(
      activityId
    );


  if (
    !activity
  ) {

    return false;

  }


  return (

    !!activity.name &&

    typeof activity.exp ===
    "number"

  );

}

// =========================================================
// TRAINING EXECUTION DATA
// =========================================================

function getTrainingExecutionData(
  activityId
) {


  const activity =
    getTrainingActivityData(
      activityId
    );


  if (
    !activity
  ) {

    return null;

  }


  return {

    activity:
      activity.id,

    rewardEXP:
      activity.exp,

    rewards:
      activity.rewards

  };

}

// =========================================================
// TRAINING DEBUG CHECK
// =========================================================

function debugTrainingActivity(
  activityId
) {


  console.log(
    "TRAINING DATA:",
    getTrainingActivityData(
      activityId
    )
  );


  console.log(
    "EXECUTION DATA:",
    getTrainingExecutionData(
      activityId
    )
  );


  return true;

}

