// =========================================================
// BRICK 296 — BATTLE ROSTER PRESENTATION PROJECTION
// =========================================================
//
// Presentation now reads the authoritative Battle deployment
// snapshot rather than projecting directly from playerTeam.
//
// =========================================================

function getBattlePlayerSlotPresentation() {


  const visualOrder = [
    3,
    2,
    1,
    4,
    5,
    6
  ];


  return visualOrder.map(
    slotNumber => {


      const slot =
        getBattleDeploymentSlot(
          "player",
          slotNumber
        );


      const member =
        getBattleDeploymentParticipant(
          "player",
          slotNumber
        );


      return {

        slotNumber:
          slotNumber,

        participantId:
          slot
            ? slot.participantId
            : null,

        member:
          member,

        active:
          !!(
            member &&
            slotNumber === 1
          )

      };
    }
  );
}


function getBattleEnemySlotPresentation() {


  const visualOrder = [
    1,
    2,
    3,
    4,
    5,
    6
  ];


  return visualOrder.map(
    slotNumber => {


      const slot =
        getBattleDeploymentSlot(
          "enemy",
          slotNumber
        );


      const enemy =
        getBattleDeploymentParticipant(
          "enemy",
          slotNumber
        );


      return {

        slotNumber:
          slotNumber,

        participantId:
          slot
            ? slot.participantId
            : null,

        enemy:
          enemy,

        active:
          !!(
            enemy &&
            slotNumber === 1
          )

      };
    }
  );
}


// =========================================================
// BRICK 301 — QUEUE TRANSITION PRESENTATION LOOKUP
// =========================================================

function getBattleRosterTransitionClass(
  slot,
  participant,
  side
) {


  const deployment =
    currentBattle.deployment;


  const transition =
    deployment &&
    deployment.lastTransition

      ? deployment.lastTransition

      : null;


  if (
    !transition ||
    transition.side !==
      side ||
    !participant ||
    !Array.isArray(
      transition.movements
    )
  ) {

    return "";
  }


  const movement =
    transition.movements.find(
      entry =>
        entry.participantId ===
          participant.id &&
        Number(
          entry.toSlot
        ) ===
        Number(
          slot.slotNumber
        )
    ) ||
    null;


  if (
    !movement
  ) {

    return "";
  }


  switch (
    movement.movementType
  ) {


    case "active_slide":

      return "transition-active-slide";


    case "reserve_promotion":

      return "transition-reserve-promotion";


    case "reserve_slide":

      return "transition-reserve-slide";


    default:

      return "";
  }
}


// =========================================================
// BRICK 297 — LIVE BATTLE ROSTER SLEEVE RENDERER
// =========================================================

function renderBattleRosterSlot(
  slot,
  side
) {


  const isPlayer =
    side ===
    "player";


  const participant =
    isPlayer
      ? slot.member
      : slot.enemy;


  const compact =
    slot.slotNumber >=
    4;


  if (
    !participant
  ) {


    return `
      <div
        class="
          battle-live-roster-slot
          ${compact ? "compact" : "full"}
          is-empty
        "
        data-side="${side}"
        data-slot="${slot.slotNumber}"
      >

        <span class="battle-live-slot-number">
          ${slot.slotNumber}
        </span>

      </div>
    `;
  }


  const name =
    participant.name ||
    "UNKNOWN";


  const image =
    participant.image ||
    "";


  const transitionClass =
    getBattleRosterTransitionClass(
      slot,
      participant,
      side
    );


  const pouchTargetState =
    getBattlePouchTargetPresentationState(
      side,
      participant.id
    );


  let primaryValue =
    "";


  let secondaryValue =
    "";


  if (
    isPlayer
  ) {


    const currentPower =
      getBattleRemainingPL(
        "player",
        participant.id
      );


    const maxPower =
      getBattleMaximumPL(
        "player",
        participant.id
      );


    primaryValue =
      `BP ${currentPower}`;


    secondaryValue =
      `/ ${maxPower}`;
  }

  else {


    const currentPower =
      getBattleRemainingPL(
        "enemy",
        participant.id
      );


    const maxPower =
      getBattleMaximumPL(
        "enemy",
        participant.id
      );


    primaryValue =
      `BP ${currentPower}`;


    secondaryValue =
      `/ ${maxPower}`;
  }


  return `
    <div
      class="
        battle-live-roster-slot
        ${compact ? "compact" : "full"}
        ${slot.active ? "is-active" : ""}
        ${transitionClass}
        ${
          pouchTargetState.valid
            ? "is-item-target"
            : ""
        }
      "
      data-side="${side}"
      data-slot="${slot.slotNumber}"
      aria-current="${slot.active ? "true" : "false"}"
      ${
        pouchTargetState.valid
          ? `
              role="button"
              tabindex="0"
              aria-label="Use selected Battle Pouch item on ${name}"
              onclick="
                confirmSelectedBattlePouchTarget(
                  '${side}',
                  '${participant.id}'
                )
              "
              onkeydown="
                if (
                  event.key === 'Enter' ||
                  event.key === ' '
                ) {
                  event.preventDefault();
                  confirmSelectedBattlePouchTarget(
                    '${side}',
                    '${participant.id}'
                  );
                }
              "
            `
          : ""
      }
    >

      <span class="battle-live-slot-number">
        ${slot.slotNumber}
      </span>

      ${
        image
          ? `
              <img
                class="battle-live-roster-portrait"
                src="${image}"
                alt="${name}"
                draggable="false"
              >
            `
          : ""
      }

      <div class="battle-live-roster-copy">

        <div class="battle-live-roster-name">
          ${name}
        </div>

        <div class="battle-live-roster-power">

          ${primaryValue}

          ${
            secondaryValue
              ? `<span>${secondaryValue}</span>`
              : ""
          }

        </div>

      </div>

    </div>
  `;
}



// =========================================================
// BRICK 301 — WITHDRAWAL PRESENTATION ECHO
// =========================================================

function renderBattleWithdrawalEcho() {


  const deployment =
    currentBattle.deployment;


  const transition =
    deployment &&
    deployment.lastTransition

      ? deployment.lastTransition

      : null;


  if (
    !transition ||
    transition.type !==
      "withdrawal_queue_advance" ||
    transition.side !==
      "player" ||
    !transition
      .withdrawnParticipantId
  ) {

    return "";
  }


  const withdrawnPlayer =
    getPlayerCharacter(
      transition
        .withdrawnParticipantId
    );


  if (
    !withdrawnPlayer
  ) {

    return "";
  }


  return `
    <div class="battle-live-withdraw-echo">

      ${
        withdrawnPlayer.image
          ? `
              <img
                src="${withdrawnPlayer.image}"
                alt=""
                draggable="false"
              >
            `
          : ""
      }

      <span>
        WITHDRAW
      </span>

    </div>
  `;
}


// =========================================================
// BRICK 298 — LIVE SIX-SLOT BATTLE ROSTERS
