function runAcademyBattleSkillDefinitionDiagnostics() {


  const skills =
    Object.values(
      ACADEMY_BATTLE_SKILL_DATABASE
    );


  const owners =
    Object.keys(
      ACADEMY_BATTLE_PILOT_PREPARED_SKILLS
    );


  const twinPalm =
    getAcademyBattleSkillDefinition(
      "academy_hinata_hyuga_twin_palm"
    );


  const crossfire =
    getAcademyBattleSkillDefinition(
      "academy_mirai_shuriken_crossfire"
    );


  const cloneFeint =
    getAcademyBattleSkillDefinition(
      "academy_izuno_clone_feint"
    );


  const pouncingStrike =
    getAcademyBattleSkillDefinition(
      "academy_izuno_pouncing_strike"
    );


  const bindingFormula =
    getAcademyBattleSkillDefinition(
      "academy_kushina_uzumaki_binding_formula"
    );


  const sealStrike =
    getAcademyBattleSkillDefinition(
      "academy_kushina_uzumaki_seal_strike"
    );


  const menmaPulse =
    getAcademyBattleSkillDefinition(
      "academy_menma_yin_chakra_pulse"
    );


  const guidance =
    getAcademyBattleSkillDefinition(
      "academy_menma_kuramas_guidance"
    );


  const result = {


    fifteenSkills:
      skills.length ===
      15,


    fiveOwners:
      owners.length ===
      5,


    threePreparedEach:
      owners.every(
        ownerId =>
          getPreparedAcademyBattleSkillIds(
            ownerId
          ).length ===
          3
      ),


    uniqueSkillIds:
      new Set(
        skills.map(
          skill =>
            skill.id
        )
      ).size ===
      15,


    twinPalmOnePacket:
      !!(
        twinPalm &&
        twinPalm
          .mechanicalPacketCount ===
          1 &&
        twinPalm
          .visualImpactCount ===
          2
      ),


    crossfireOnePacket:
      !!(
        crossfire &&
        crossfire
          .mechanicalPacketCount ===
          1 &&
        crossfire
          .traits
          .includes(
            "multi_hit_presentation"
          )
      ),


    sourceScopedFeint:
      !!(
        cloneFeint &&
        cloneFeint.state &&
        pouncingStrike &&
        pouncingStrike
          .conditional
          .stateKey ===
          "feinted_opening"
      ),


    bindingSealChain:
      !!(
        bindingFormula &&
        bindingFormula.state &&
        sealStrike &&
        sealStrike
          .conditional
          .stateKey ===
          "binding_formula"
      ),


    menmaUsesAttachedSummonAuthority:
      !!(
        menmaPulse &&
        menmaPulse.requirements
          .some(
            requirement =>
              requirement.kind ===
              "attached_summon_access" &&
              requirement.entityId ===
                "menma_nine_tails"
          )
      ),


    guidanceUsesAttachedSummonAccess:
      !!(
        guidance &&
        guidance.stateOwnerRef &&
        guidance.stateOwnerRef.type ===
          "attached_summon_access" &&
        guidance.stateOwnerRef.id ===
          "academy_menma_menma_nine_tails"
      ),


    approvedDamageProfilesPresent:
      skills
        .filter(
          skill =>
            skill.resolutionKind ===
              "direct_damage"
        )
        .every(
          skill =>
            skill.damageProfile &&
            Number(
              skill.damageProfile.coefficient
            ) > 0
        )

  };


  result.pass =
    Object.values(
      result
    ).every(
      value =>
        value ===
        true
    );


  console.table(
    result
  );


  return result;
}



