// SAVE & DEVELOPMENT SYSTEMS
// #########################################################

// =========================================================
// BRICK 156 — DEVELOPMENT BATTLE STATE RESTORE
// BRICK 607 — ENEMY PARTICIPANT IDENTITY RESTORE
// =========================================================
//
// Restores Battle-local deployment and runtime state before
// reopening Combat.
//
// Old snapshots remain compatible.
//
// =========================================================

function restoreTestState() {


  const saved =
    sessionStorage.getItem(
      "shinobiTestState"
    );


  if (
    !saved
  ) {

    return;
  }


  const state =
    JSON.parse(
      saved
    );


  // =========================================
  // REGION
  // =========================================

  if (
    state.regionKey &&
    worldRegions[
      state.regionKey
    ]
  ) {


    selectedRegionKey =
      state.regionKey;


    if (
      state.locationId
    ) {


      selectedLocationNode =
        worldRegions[
          state.regionKey
        ]
          .locations
          .find(
            location =>
              location.id ===
              state.locationId
          ) ||
        null;
    }
  }


  // =========================================
  // ENEMY
  // =========================================

  if (
    state.enemyId &&
    enemyDatabase[
      state.enemyId
    ]
  ) {


    selectedEnemy =
      enemyDatabase[
        state.enemyId
      ];


    currentBattle.enemy =
      selectedEnemy;


    currentBattle.encounterEnemy =
      selectedEnemy;
  }


  const restoredEnemyParticipantIds =
    Array.isArray(state.enemyParticipantIds) &&
    state.enemyParticipantIds.length > 0
      ? state.enemyParticipantIds
      : selectedEnemy
        ? [selectedEnemy.id]
        : [];


  setBattleEnemyParticipants(
    restoredEnemyParticipantIds
  );


  // =========================================
  // BATTLE IDENTITY
  // =========================================

  currentBattle.battleId =
    state.battleId ||
    null;


  currentBattle.encounterId =
    state.encounterId ||
    null;


  currentBattle.characterId =
    state.characterId ||
    null;


  currentBattle.completedAt =
    Number(
      state.completedAt
    ) ||
    null;


  currentBattle.claimedAt =
    Number(
      state.claimedAt
    ) ||
    null;


  currentBattle.completionRecorded =
    state.completionRecorded ===
    true;


  // =========================================
  // BATTLE POWER
  // =========================================

  currentBattle.enemyPower =
    typeof state.enemyPower ===
      "number"

      ? state.enemyPower

      : 0;


  currentBattle.enemyMaxPower =
    typeof state.enemyMaxPower ===
      "number"

      ? state.enemyMaxPower

      : 0;


  // =========================================
  // DEPLOYMENT
  // =========================================

  currentBattle.deployment =
    normalizeBattleDeployment(
      state.deployment,
      state.activePlayerId ||
        state.characterId ||
        null
    );


  const deploymentActivePlayer =
    syncBattleActivePlayerFromDeployment();


  syncBattleActiveEnemyFromDeployment();


  if (
    !deploymentActivePlayer &&
    state.activePlayerId
  ) {


    currentBattle.activePlayer =
      getPlayerCharacter(
        state.activePlayerId
      ) ||
      playerTeam[
        0
      ] ||
      null;
  }


  if (
    !currentBattle.characterId &&
    currentBattle.activePlayer
  ) {


    currentBattle.characterId =
      currentBattle
        .activePlayer
        .id;
  }


  // =========================================
  // BRICKS 302–304 — BATTLE RUNTIME
  // =========================================

  restoreBattleRuntimeState(
    state.runtime
  );


  // =========================================
  // BATTLE DATA
  // =========================================

  currentBattle.lastDamage =
    typeof state.lastDamage ===
      "number"

      ? state.lastDamage

      : 0;


  currentBattle.battleOver =
    state.battleOver ===
    true;


  currentBattle.battleLog =
    Array.isArray(
      state.battleLog
    )

      ? state.battleLog

      : [];


  currentBattle.rewards =
    state.rewards &&
    typeof state.rewards ===
      "object"

      ? state.rewards

      : currentBattle.rewards;


  currentBattle.contributions =
    state.contributions &&
    typeof state.contributions ===
      "object"

      ? state.contributions

      : {};


  // =========================================
  // RESTORE SCREEN
  // =========================================

  if (
    state.overlayType ===
      "victory" &&
    selectedEnemy
  ) {


    currentBattle.active =
      false;


    currentBattle.battleOver =
      true;


    openOverlay(
      "victory"
    );


    return;
  }


  if (
    state.overlayType ===
      "combat" &&
    selectedEnemy
  ) {


    currentBattle.active =
      true;


    openOverlay(
      "combat"
    );


    return;
  }


  if (
    state.overlayType ===
      "battle" &&
    selectedRegionKey
  ) {


    openOverlay(
      "battle"
    );


    return;
  }


  if (
    state.overlayType ===
      "region" &&
    selectedRegionKey
  ) {


    openRegionHub(
      selectedRegionKey
    );
  }
}

